import { Question } from '@/types/question';

const questions: Question[] = [
  { id: 'pg-admin-l3-001', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Streaming Replication', question: 'What is streaming replication in PostgreSQL?', options: ['A method where the primary server continuously streams WAL records to standby servers in real-time, keeping them nearly synchronized without waiting for WAL file completion', 'A method for streaming query results', 'A data import mechanism', 'A backup compression technique'], correctAnswer: 0, explanation: 'Streaming replication sends WAL records from the primary to standbys as they are generated, without waiting for a full 16MB WAL segment to be archived. This provides much lower replication lag compared to log-shipping. Standbys can serve read-only queries (hot standby).', codeSnippet: "-- Primary: postgresql.conf\nwal_level = replica\nmax_wal_senders = 10\nmax_replication_slots = 10\n\n-- Primary: pg_hba.conf\nhost replication repl_user 10.0.0.0/24 scram-sha-256\n\n-- Standby: create with pg_basebackup\npg_basebackup -h primary -D /var/lib/postgresql/data \\\n  -U repl_user -Fp -Xs -P -R\n\n-- -R flag creates standby.signal and sets\n-- primary_conninfo in postgresql.auto.conf", tags: ['admin', 'streaming-replication', 'wal', 'standby'] },
  { id: 'pg-admin-l3-002', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Streaming Replication', question: 'What is the difference between synchronous and asynchronous replication?', options: ['Synchronous is always faster', 'In asynchronous replication (default), the primary does not wait for standbys to confirm WAL receipt; in synchronous replication, the primary waits for at least one standby to confirm write/flush before committing, guaranteeing zero data loss at the cost of latency', 'Asynchronous means delayed by hours', 'Synchronous only works on localhost'], correctAnswer: 1, explanation: 'Asynchronous replication has no write latency penalty but risks data loss if the primary fails before WAL reaches the standby. Synchronous replication guarantees zero data loss (RPO=0) but adds network round-trip latency to every commit. Configure with synchronous_standby_names and synchronous_commit.', codeSnippet: "-- Enable synchronous replication:\n-- postgresql.conf on primary:\nsynchronous_standby_names = 'FIRST 1 (standby1, standby2)'\nsynchronous_commit = on  -- default\n\n-- Options for synchronous_commit:\n-- 'on'           - wait for local WAL flush (no sync standby wait)\n-- 'remote_write' - wait for standby OS buffer write\n-- 'remote_apply' - wait for standby to replay\n-- 'off'          - no flush wait (risk of data loss)\n\n-- Check sync status:\nSELECT application_name, sync_state\nFROM pg_stat_replication;", tags: ['admin', 'replication', 'synchronous', 'asynchronous'] },
  { id: 'pg-admin-l3-003', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'WAL Archiving', question: 'What is WAL archiving and why is it needed?', options: ['Compressing WAL files to save space', 'Copying completed WAL segments to a separate archive location using archive_command — required for point-in-time recovery (PITR) and as a backup mechanism for WAL segments that would otherwise be recycled', 'Deleting old WAL files', 'Encrypting WAL files'], correctAnswer: 1, explanation: 'WAL archiving copies each completed 16MB WAL segment to an archive before it can be recycled. This provides: (1) a continuous backup of all changes, (2) the ability to replay changes to any point in time (PITR), (3) a safety net for standbys that fall behind. Configured via archive_mode and archive_command.', codeSnippet: "-- postgresql.conf:\narchive_mode = on\narchive_command = 'cp %p /archive/wal/%f'\n-- %p = source path, %f = filename\n\n-- Using a more robust archive command:\narchive_command = 'test ! -f /archive/wal/%f && cp %p /archive/wal/%f'\n\n-- Archive to S3 (using aws cli):\narchive_command = 'aws s3 cp %p s3://my-wal-archive/%f'\n\n-- Monitor archiving:\nSELECT * FROM pg_stat_archiver;", tags: ['admin', 'wal-archiving', 'pitr', 'archive-command'] },
  { id: 'pg-admin-l3-004', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'What is point-in-time recovery (PITR)?', options: ['Recovering from a specific backup', 'The ability to restore a database to any specific moment in time by starting from a base backup and replaying WAL records up to the desired timestamp or transaction ID', 'Recovering from the last checkpoint', 'Recovering deleted rows'], correctAnswer: 1, explanation: 'PITR combines a physical base backup (pg_basebackup) with archived WAL segments. You restore the base backup, then configure recovery to replay WAL segments up to a specific timestamp, transaction ID, or LSN. This allows recovery from accidental deletions, bad migrations, or corruption.', codeSnippet: "-- Step 1: Restore base backup\npg_basebackup -D /recovery/data ...\n\n-- Step 2: Configure recovery target\n-- postgresql.conf:\nrestore_command = 'cp /archive/wal/%f %p'\nrecovery_target_time = '2024-06-15 14:30:00'\nrecovery_target_action = 'promote'\n\n-- Step 3: Create recovery signal\ntouch /recovery/data/recovery.signal\n\n-- Step 4: Start PostgreSQL\npg_ctl start -D /recovery/data\n\n-- Recovery stops at 14:30:00\n-- Server promotes to read-write mode", tags: ['admin', 'pitr', 'point-in-time-recovery', 'restore'] },
  { id: 'pg-admin-l3-005', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Connection Pooling', question: 'What is pgBouncer and why is it needed?', options: ['A PostgreSQL monitoring tool', 'A lightweight connection pooler that sits between clients and PostgreSQL, multiplexing many client connections onto fewer database connections — reduces memory overhead and connection setup cost', 'A load balancer for read replicas', 'A query cache layer'], correctAnswer: 1, explanation: 'Each PostgreSQL connection uses ~5-10MB of memory (backend process). With thousands of clients, this becomes unsustainable. pgBouncer maintains a pool of database connections and assigns them to clients on demand. This reduces memory usage, connection overhead, and supports far more concurrent clients than max_connections allows.', codeSnippet: "-- pgbouncer.ini:\n[databases]\nmydb = host=127.0.0.1 port=5432 dbname=mydb\n\n[pgbouncer]\nlisten_port = 6432\nlisten_addr = 0.0.0.0\nauth_type = scram-sha-256\nauth_file = /etc/pgbouncer/userlist.txt\npool_mode = transaction\nmax_client_conn = 1000\ndefault_pool_size = 20\n\n-- Connect through pgBouncer:\npsql -h localhost -p 6432 -U app_user mydb", tags: ['admin', 'pgbouncer', 'connection-pooling'] },
  { id: 'pg-admin-l3-006', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Connection Pooling', question: 'What are the pool modes in pgBouncer?', options: ['Single and multi', 'Session mode (connection held for entire session), transaction mode (returned after each transaction), and statement mode (returned after each statement) — transaction mode is most common', 'Read and write modes', 'Fast and slow modes'], correctAnswer: 1, explanation: 'Session mode: connection assigned for the entire client session (like no pooling, but with connection reuse). Transaction mode: connection assigned per transaction (best balance). Statement mode: connection returned after each statement (most aggressive, but breaks multi-statement transactions and prepared statements).', codeSnippet: "-- pgbouncer.ini:\n\n-- Session mode: connection per session\npool_mode = session\n-- Supports: prepared statements, SET, LISTEN/NOTIFY\n-- Least aggressive pooling\n\n-- Transaction mode: connection per transaction (recommended)\npool_mode = transaction\n-- Breaks: session-level features (SET, prepared statements)\n-- Best for most applications\n\n-- Statement mode: connection per statement\npool_mode = statement\n-- Most aggressive, breaks transactions\n-- Only for simple single-statement workloads", tags: ['admin', 'pgbouncer', 'pool-modes'] },
  { id: 'pg-admin-l3-007', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Streaming Replication', question: 'What are replication slots and why are they important?', options: ['Slots for connecting additional replicas', 'A mechanism that ensures the primary retains WAL segments needed by a standby — prevents the primary from recycling WAL that the standby has not yet consumed, avoiding replication breaks', 'Time slots for replication scheduling', 'Memory slots for WAL buffers'], correctAnswer: 1, explanation: 'Without replication slots, the primary may recycle WAL segments before a standby has received them (especially during standby downtime). Replication slots track each standby\'s position and prevent WAL cleanup ahead of it. Caution: a stale slot can cause unlimited WAL accumulation on the primary.', codeSnippet: "-- Create a physical replication slot:\nSELECT pg_create_physical_replication_slot('standby1_slot');\n\n-- Standby configuration:\n-- primary_conninfo = '...'\n-- primary_slot_name = 'standby1_slot'\n\n-- Monitor slot lag:\nSELECT slot_name, active,\n  pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn) AS lag_bytes,\n  pg_size_pretty(pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn)) AS lag\nFROM pg_replication_slots;\n\n-- Drop a stale slot (CAUTION: releases retained WAL):\nSELECT pg_drop_replication_slot('old_standby_slot');", tags: ['admin', 'replication', 'replication-slots', 'wal-retention'] },
  { id: 'pg-admin-l3-008', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'WAL Archiving', question: 'What is the wal_level setting and what are its options?', options: ['Controls WAL file size', 'Controls how much information is written to WAL — minimal (crash recovery only), replica (adds replication/archiving support), or logical (adds logical decoding support)', 'Controls WAL compression', 'Controls WAL encryption'], correctAnswer: 1, explanation: 'wal_level determines the WAL detail: minimal writes only enough for crash recovery; replica (default) adds enough for streaming replication and PITR; logical adds information needed for logical decoding (logical replication). Higher levels write more WAL data. Changing requires a restart.', codeSnippet: "-- Check current level:\nSHOW wal_level;  -- replica (default since PG 10)\n\n-- Set in postgresql.conf:\nwal_level = replica   -- for streaming replication / PITR\nwal_level = logical   -- for logical replication\nwal_level = minimal   -- minimum WAL (no replication)\n\n-- Requires restart:\n-- pg_ctl restart -D /var/lib/postgresql/data\n\n-- minimal: fastest writes, no replication\n-- replica: default, supports physical replication\n-- logical: supports logical replication + physical", tags: ['admin', 'wal', 'wal-level', 'configuration'] },
  { id: 'pg-admin-l3-009', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'What recovery targets can you specify for PITR?', options: ['Only timestamp', 'recovery_target_time (timestamp), recovery_target_xid (transaction ID), recovery_target_lsn (WAL position), and recovery_target_name (named restore point created with pg_create_restore_point())', 'Only transaction ID', 'Only LSN position'], correctAnswer: 1, explanation: 'PostgreSQL supports four recovery target types: time (stop at a specific timestamp), xid (stop after a specific transaction), lsn (stop at a specific WAL position), and name (stop at a named restore point). recovery_target_inclusive controls whether the target itself is included or excluded.', codeSnippet: "-- By timestamp:\nrecovery_target_time = '2024-06-15 14:30:00+00'\n\n-- By transaction ID:\nrecovery_target_xid = '12345678'\n\n-- By WAL position:\nrecovery_target_lsn = '0/15A8C00'\n\n-- By named restore point:\n-- First create the restore point:\nSELECT pg_create_restore_point('before_migration');\n-- Then recover to it:\nrecovery_target_name = 'before_migration'\n\n-- Control inclusion:\nrecovery_target_inclusive = true  -- include the target\n\n-- What to do after reaching target:\nrecovery_target_action = 'promote'  -- or 'pause' or 'shutdown'", tags: ['admin', 'pitr', 'recovery-targets'] },
  { id: 'pg-admin-l3-010', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Streaming Replication', question: 'How do you set up a hot standby server?', options: ['Install a separate PostgreSQL instance', 'Use pg_basebackup to create a copy of the primary, configure connection to primary, and start in standby mode — the standby continuously receives and replays WAL while accepting read-only queries', 'Copy the data directory manually', 'Use pg_dump to create the standby'], correctAnswer: 1, explanation: 'A hot standby serves read-only queries while continuously replicating from the primary. Setup: (1) configure the primary for replication, (2) use pg_basebackup with -R to create the standby data directory and auto-configure recovery settings, (3) start the standby.', codeSnippet: "-- Step 1: Primary config\n-- postgresql.conf:\nwal_level = replica\nmax_wal_senders = 10\nhot_standby = on\n\n-- pg_hba.conf:\nhost replication repl_user 10.0.0.0/24 scram-sha-256\n\n-- Create replication role:\nCREATE ROLE repl_user WITH REPLICATION LOGIN PASSWORD 'secret';\n\n-- Step 2: Create standby\npg_basebackup -h primary_host -U repl_user \\\n  -D /var/lib/postgresql/data -Fp -Xs -P -R\n\n-- Step 3: Start standby\npg_ctl start -D /var/lib/postgresql/data\n-- Standby accepts read-only queries immediately", tags: ['admin', 'hot-standby', 'streaming-replication', 'setup'] },
  { id: 'pg-admin-l3-011', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Connection Pooling', question: 'What limitations does pgBouncer transaction pooling introduce?', options: ['No limitations', 'Session-level features break: SET commands, prepared statements (without protocol-level support), LISTEN/NOTIFY, advisory locks, and temporary tables do not persist across transactions', 'Only SELECT queries work', 'Transactions are limited to 30 seconds'], correctAnswer: 1, explanation: 'In transaction mode, the database connection is returned to the pool after each transaction. Any session state (SET variables, prepared statements, temp tables, advisory locks, LISTEN registrations) is lost. Applications must be designed to work within single transactions or use session mode for features that require persistent state.', codeSnippet: "-- These break in transaction pooling mode:\n\n-- SET is lost after transaction:\nBEGIN;\nSET search_path TO myschema;  -- works in this TX\nCOMMIT;\n-- Next TX: search_path is reset!\n\n-- Prepared statements lost:\nPREPARE my_stmt AS SELECT $1;\nEXECUTE my_stmt('test');  -- may fail\n\n-- Workarounds:\n-- Use SET LOCAL inside transactions\n-- Use server-side prepared statements in libpq\n-- pgBouncer 1.21+ supports protocol-level prepared stmts\n-- Use session mode for apps needing these features", tags: ['admin', 'pgbouncer', 'transaction-pooling', 'limitations'] },
  { id: 'pg-admin-l3-012', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'WAL Archiving', question: 'What is restore_command and how is it used?', options: ['A command to restore backups', 'A shell command that PostgreSQL executes to retrieve archived WAL segments during recovery — it copies WAL files from the archive to the pg_wal directory for replay', 'A command to restart PostgreSQL', 'A command to restore dropped tables'], correctAnswer: 1, explanation: 'restore_command is the counterpart of archive_command. During recovery (PITR or standby startup), PostgreSQL calls this command for each WAL segment it needs. The command must copy the requested WAL file from the archive to the specified path. If it fails (returns non-zero), PostgreSQL tries streaming replication.', codeSnippet: "-- postgresql.conf (on standby or recovery server):\nrestore_command = 'cp /archive/wal/%f %p'\n-- %f = WAL filename needed\n-- %p = path where PostgreSQL expects the file\n\n-- From S3:\nrestore_command = 'aws s3 cp s3://my-wal-archive/%f %p'\n\n-- Using pgBackRest:\nrestore_command = 'pgbackrest --stanza=mydb archive-get %f \"%p\"'\n\n-- The command should:\n-- Return 0 on success (file copied)\n-- Return non-zero if file not found (normal at end of archive)", tags: ['admin', 'wal-archiving', 'restore-command', 'pitr'] },
  { id: 'pg-admin-l3-013', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Streaming Replication', question: 'What is the difference between physical and logical replication?', options: ['Physical is faster, logical is slower', 'Physical replication streams raw WAL bytes for exact binary copies; logical replication decodes WAL into logical changes (INSERT/UPDATE/DELETE) allowing selective table replication and cross-version replication', 'Physical uses more disk space', 'Logical requires more memory'], correctAnswer: 1, explanation: 'Physical replication creates byte-for-byte identical copies (entire cluster). Logical replication decodes WAL into row-level changes, enabling: selective table replication, replication between different PG major versions, replication to different systems, and bidirectional replication setups.', codeSnippet: "-- Physical replication: entire cluster, same PG version\npg_basebackup -h primary -D /standby/data -R\n-- Standby is exact binary copy\n\n-- Logical replication: selective, cross-version\n-- On publisher:\nCREATE PUBLICATION my_pub FOR TABLE orders, customers;\n\n-- On subscriber (can be different PG version):\nCREATE SUBSCRIPTION my_sub\n  CONNECTION 'host=publisher dbname=mydb'\n  PUBLICATION my_pub;", tags: ['admin', 'replication', 'physical', 'logical', 'comparison'] },
  { id: 'pg-admin-l3-014', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'What is pg_basebackup and how does it work?', options: ['A tool for logical backups', 'A tool that creates a physical backup of the entire PostgreSQL cluster by streaming data directly from a running server — it can include WAL for self-contained backups', 'A tool for incremental backups', 'A tool for backup compression'], correctAnswer: 1, explanation: 'pg_basebackup connects to a running PostgreSQL server and copies the entire data directory. With -Xs (stream), it also streams WAL during the backup so the result is self-contained and consistent. With -R, it auto-configures the backup as a standby. It is the foundation for PITR and replica creation.', codeSnippet: "# Basic backup:\npg_basebackup -h primary -U repl_user \\\n  -D /backup/base -Fp -Xs -P\n\n# Flags:\n# -D: destination directory\n# -Fp: plain format (directory)\n# -Ft: tar format\n# -Xs: stream WAL during backup (self-contained)\n# -Xf: fetch WAL at end\n# -P: show progress\n# -R: configure as standby\n# -z: compress (tar format)\n# --checkpoint=fast: start backup quickly\n\n# Compressed tar backup:\npg_basebackup -h primary -U repl_user \\\n  -D /backup/ -Ft -z -Xs -P", tags: ['admin', 'pg-basebackup', 'physical-backup'] },
  { id: 'pg-admin-l3-015', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Connection Pooling', question: 'How do you monitor pgBouncer?', options: ['Use pg_stat_activity', 'Connect to the pgBouncer admin console (database = pgbouncer) and run SHOW commands — SHOW POOLS, SHOW CLIENTS, SHOW SERVERS, SHOW STATS', 'Check pgBouncer log files only', 'Use pg_stat_statements'], correctAnswer: 1, explanation: 'pgBouncer provides an admin console accessible by connecting to the special "pgbouncer" database. SHOW POOLS shows pool utilization. SHOW CLIENTS shows client connections. SHOW SERVERS shows database connections. SHOW STATS shows request counts and timing.', codeSnippet: "-- Connect to pgBouncer admin console:\npsql -h localhost -p 6432 pgbouncer\n\n-- Key monitoring commands:\nSHOW POOLS;    -- pool utilization per database/user\nSHOW CLIENTS;  -- all client connections\nSHOW SERVERS;  -- all server (database) connections\nSHOW STATS;    -- request statistics\nSHOW CONFIG;   -- current configuration\nSHOW LISTS;    -- pool sizes and free counts\nSHOW MEM;      -- memory usage\n\n-- Key metrics from SHOW POOLS:\n-- cl_active:  clients executing queries\n-- cl_waiting: clients waiting for a connection\n-- sv_active:  server connections in use\n-- sv_idle:    idle server connections", tags: ['admin', 'pgbouncer', 'monitoring'] },
  { id: 'pg-admin-l3-016', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Streaming Replication', question: 'How do you promote a standby to become the new primary?', options: ['Restart the standby', 'Call pg_promote() function, use pg_ctl promote command, or create a trigger file — the standby exits recovery mode and becomes a read-write primary', 'Copy the primary data directory to the standby', 'Run ALTER SYSTEM PROMOTE'], correctAnswer: 1, explanation: 'Promotion makes a standby server become a primary. Three methods: (1) SELECT pg_promote() from SQL, (2) pg_ctl promote -D datadir from command line, (3) create the promote_trigger_file. After promotion, the server accepts writes. Other standbys must be reconfigured to follow the new primary.', codeSnippet: "-- Method 1: SQL function (PG 12+)\nSELECT pg_promote(wait := true, wait_seconds := 60);\n\n-- Method 2: Command line\npg_ctl promote -D /var/lib/postgresql/data\n\n-- Method 3: Trigger file\n-- postgresql.conf: promote_trigger_file = '/tmp/promote'\ntouch /tmp/promote\n\n-- After promotion:\n-- 1. Verify the new primary accepts writes\n-- 2. Reconfigure remaining standbys to point to new primary\n-- 3. Update application connection strings\n-- 4. Optionally rebuild old primary as a standby", tags: ['admin', 'replication', 'promotion', 'failover'] },
  { id: 'pg-admin-l3-017', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'WAL Archiving', question: 'What is archive_timeout and when should you use it?', options: ['Maximum time to keep archived WAL files', 'Forces PostgreSQL to switch to a new WAL segment after the specified time — ensures WAL segments are archived regularly even during low-activity periods, limiting potential data loss window', 'Timeout for the archive_command', 'Maximum archive storage duration'], correctAnswer: 1, explanation: 'WAL segments are archived only when complete (16MB). During low activity, a segment might take hours to fill. archive_timeout forces a segment switch after the specified time (e.g., 60s), ensuring regular archiving. This limits the data loss window for PITR. The downside is generating partially-filled 16MB files.', codeSnippet: "-- Force WAL switch every 5 minutes:\narchive_timeout = 300  -- in seconds\n\n-- This means:\n-- Maximum data loss window = 5 minutes\n-- But generates one 16MB file every 5 minutes\n-- even if only a few KB of WAL was written\n\n-- Check WAL segment size:\nSHOW wal_segment_size;  -- 16MB\n\n-- Manual WAL switch:\nSELECT pg_switch_wal();", tags: ['admin', 'wal-archiving', 'archive-timeout', 'data-loss'] },
  { id: 'pg-admin-l3-018', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'What is recovery_target_action?', options: ['The action to take if recovery fails', 'Controls what PostgreSQL does when it reaches the recovery target — promote (become primary), pause (wait for user to check and decide), or shutdown (stop the server)', 'The action to perform during recovery', 'Controls recovery speed'], correctAnswer: 1, explanation: 'After reaching the recovery target: promote makes the server writable immediately; pause keeps the server in read-only mode at the target point for inspection (you can then promote manually or let it continue); shutdown stops the server (useful for creating a snapshot at the exact recovery point).', codeSnippet: "-- Promote immediately (most common):\nrecovery_target_action = 'promote'\n\n-- Pause for inspection (useful for verification):\nrecovery_target_action = 'pause'\n-- Then manually: SELECT pg_wal_replay_resume();\n-- Or: SELECT pg_promote();\n\n-- Shutdown at target:\nrecovery_target_action = 'shutdown'\n-- Useful for creating a backup at exact PITR point\n-- Restart to continue recovery or modify target", tags: ['admin', 'pitr', 'recovery-target-action'] },
  { id: 'pg-admin-l3-019', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Connection Pooling', question: 'How do you size the pgBouncer connection pool?', options: ['Set it equal to max_connections', 'Match default_pool_size to the number of CPU cores on the database server — a good starting point is 2-3x CPU cores; monitor and adjust based on wait queue length and query patterns', 'Always use 100 connections', 'Use 1 connection per client'], correctAnswer: 1, explanation: 'Optimal pool size depends on workload: CPU-bound queries benefit from core_count connections. I/O-bound queries can use more (2-4x cores). Monitor cl_waiting in SHOW POOLS — if clients wait often, increase pool size. If server connections sit idle, decrease. The total across all pools should not exceed max_connections.', codeSnippet: "-- pgbouncer.ini sizing:\ndefault_pool_size = 20    -- connections per user/db pair\nmin_pool_size = 5          -- keep this many open\nreserve_pool_size = 5      -- extra for burst\nreserve_pool_timeout = 3   -- seconds before using reserve\nmax_client_conn = 1000     -- max client connections\nmax_db_connections = 50    -- max per database\n\n-- Rule of thumb for default_pool_size:\n-- CPU-bound: num_cores\n-- Mixed:     num_cores * 2\n-- I/O-bound: num_cores * 4\n\n-- Monitor and adjust:\n-- SHOW POOLS; -- check cl_waiting\n-- If cl_waiting > 0 consistently: increase pool", tags: ['admin', 'pgbouncer', 'pool-sizing', 'performance'] },
  { id: 'pg-admin-l3-020', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Streaming Replication', question: 'What is max_wal_senders and how should it be configured?', options: ['Maximum WAL file count', 'The maximum number of concurrent connections from WAL receivers (standbys and backup tools) — set it to at least the number of standbys plus slots for pg_basebackup and any WAL monitoring tools', 'Maximum WAL segment size', 'Maximum WAL write speed'], correctAnswer: 1, explanation: 'max_wal_senders limits concurrent replication connections. Each standby uses one sender. pg_basebackup uses one or two senders. Set it to: number_of_standbys + number_of_backup_slots + some_spare. Exceeding this limit causes replication connection failures. Default is 10.', codeSnippet: "-- Set based on needs:\nmax_wal_senders = 10\n\n-- Calculation:\n-- 2 standbys: 2\n-- pg_basebackup: 2 (data + WAL stream)\n-- Monitoring tools: 1\n-- Spare: 5\n-- Total: 10\n\n-- Check current usage:\nSELECT count(*) AS active_senders,\n  current_setting('max_wal_senders')::int AS max_senders\nFROM pg_stat_replication;", tags: ['admin', 'replication', 'max-wal-senders', 'configuration'] },
  { id: 'pg-admin-l3-021', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'WAL Archiving', question: 'What happens if archive_command fails?', options: ['WAL segments are deleted anyway', 'PostgreSQL retries the archive_command for the same WAL segment — it will not recycle that segment until archiving succeeds, which can cause WAL to accumulate on disk', 'The server shuts down', 'Replication stops'], correctAnswer: 1, explanation: 'If archive_command returns a non-zero exit code, PostgreSQL retries periodically. The WAL segment is not recycled until successfully archived. Persistent failures cause WAL to accumulate on pg_wal, potentially filling the disk. Monitor pg_stat_archiver.failed_count and set up alerts.', codeSnippet: "-- Check archiving status:\nSELECT archived_count, failed_count,\n  last_archived_wal, last_archived_time,\n  last_failed_wal, last_failed_time\nFROM pg_stat_archiver;\n\n-- Alert on failures:\n-- If failed_count increases, investigate:\n-- 1. Check archive_command permissions\n-- 2. Check destination disk space\n-- 3. Check network connectivity (for remote archives)\n\n-- Manual WAL cleanup (DANGEROUS):\n-- pg_archivecleanup /var/lib/postgresql/data/pg_wal <oldest_needed_wal>\n-- Only use if you understand the PITR implications", tags: ['admin', 'wal-archiving', 'failure-handling', 'monitoring'] },
  { id: 'pg-admin-l3-022', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'What is the timeline concept in PostgreSQL recovery?', options: ['A backup schedule', 'Each recovery creates a new timeline — timelines branch from the recovery point, preventing confusion between the original and recovered history; timeline IDs are encoded in WAL filenames', 'The order of WAL files', 'A replication lag measurement'], correctAnswer: 1, explanation: 'When a server is promoted after recovery, it starts a new timeline to distinguish WAL generated on the original server from WAL generated after recovery. Timeline IDs are embedded in WAL filenames (e.g., 00000002000000000000001A). .history files record the branching points. You can specify recovery_target_timeline to follow a specific branch.', codeSnippet: "-- Timeline is visible in WAL filenames:\n-- 000000010000000000000001  -- timeline 1\n-- 000000020000000000000001  -- timeline 2 (after first recovery)\n\n-- Recovery along specific timeline:\nrecovery_target_timeline = 'latest'  -- default: follow latest\nrecovery_target_timeline = 2         -- follow timeline 2\n\n-- Check current timeline:\nSELECT timeline_id FROM pg_control_checkpoint();\n\n-- Timeline history files (.history) in pg_wal:\n-- 00000002.history records when timeline 2 branched from 1", tags: ['admin', 'pitr', 'timelines', 'recovery'] },
  { id: 'pg-admin-l3-023', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Connection Pooling', question: 'What is the difference between pgBouncer and built-in connection pooling?', options: ['PostgreSQL has built-in pooling that is better', 'PostgreSQL does not have built-in connection pooling — pgBouncer is an external process; however, some drivers (like libpq with connection pooling or application-level pools like HikariCP) provide client-side pooling that can be combined with pgBouncer', 'pgBouncer is built into PostgreSQL', 'There is no difference'], correctAnswer: 1, explanation: 'PostgreSQL has no built-in connection pooler (though there are proposals). pgBouncer sits between clients and PostgreSQL. Client-side pools (HikariCP, c3p0, pgPool-II) manage connections within a single application. For multi-service architectures, pgBouncer provides centralized pooling across all applications. They can be used together.', codeSnippet: "-- Architecture with pgBouncer:\n-- App Server 1 (HikariCP pool=10) --> pgBouncer (pool=20) --> PostgreSQL\n-- App Server 2 (HikariCP pool=10) --/\n-- App Server 3 (HikariCP pool=10) --/\n\n-- Without pgBouncer: 30 direct connections\n-- With pgBouncer: 20 database connections serve 30+ clients\n\n-- pgBouncer alternatives:\n-- PgPool-II: pooling + load balancing + failover\n-- Odyssey: multi-threaded pooler (by Yandex)\n-- Supavisor: Elixir-based pooler", tags: ['admin', 'pgbouncer', 'connection-pooling', 'comparison'] },
  { id: 'pg-admin-l3-024', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Streaming Replication', question: 'What is cascading replication?', options: ['Replication from primary to all standbys simultaneously', 'A standby server can relay WAL to downstream standbys — creating a chain: primary -> standby1 -> standby2; this reduces network load on the primary', 'Automatic failover chain', 'Replication across data centers'], correctAnswer: 1, explanation: 'Cascading replication allows a standby to act as a WAL relay for other standbys. This is useful for: reducing network load on the primary, replicating across data centers (local standby relays to remote standbys), and creating replication hierarchies. Cascading adds replication lag.', codeSnippet: "-- Primary -> Standby1 -> Standby2 (cascading)\n\n-- Standby1 config: connects to primary\nprimary_conninfo = 'host=primary port=5432 user=repl_user'\n\n-- Standby2 config: connects to standby1\nprimary_conninfo = 'host=standby1 port=5432 user=repl_user'\n\n-- Monitor the chain:\n-- On primary:\nSELECT client_addr, application_name\nFROM pg_stat_replication;\n-- Shows only standby1\n\n-- On standby1:\nSELECT client_addr, application_name\nFROM pg_stat_replication;\n-- Shows standby2 (cascading)", tags: ['admin', 'replication', 'cascading', 'topology'] },
  { id: 'pg-admin-l3-025', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'WAL Archiving', question: 'What is pg_archivecleanup used for?', options: ['Cleaning up the archive directory', 'A utility that removes WAL files from the archive that are no longer needed by a standby — commonly used as archive_cleanup_command on standbys to prevent unlimited archive growth', 'Cleaning up corrupted archives', 'Cleaning up temporary archive files'], correctAnswer: 1, explanation: 'pg_archivecleanup removes WAL files from the archive directory that are older than a specified WAL segment (typically the last restored segment). Used as archive_cleanup_command on standbys or manually during maintenance. It keeps the archive from growing unboundedly.', codeSnippet: "-- On standby, clean up as part of recovery:\n-- postgresql.conf:\narchive_cleanup_command = 'pg_archivecleanup /archive/wal %r'\n-- %r = last valid restart point WAL file\n\n-- Manual cleanup:\npg_archivecleanup /archive/wal 00000001000000000000007A\n-- Removes all WAL files older than 7A\n\n-- Alternative: use pgBackRest or Barman for\n-- lifecycle-managed WAL archiving", tags: ['admin', 'wal-archiving', 'cleanup', 'pg-archivecleanup'] },
  { id: 'pg-admin-l3-026', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'How do you test a PITR setup?', options: ['Just hope it works', 'Regularly perform test recoveries: take a base backup, generate some test data, create a restore point, generate more data, then recover to the restore point and verify the expected data state', 'Run VERIFY PITR command', 'Test is automatic in PostgreSQL'], correctAnswer: 1, explanation: 'PITR testing should be a regular operational practice. Steps: (1) take a base backup, (2) run workload, (3) record a timestamp or create a restore point, (4) continue workload, (5) restore to the recorded point, (6) verify data integrity. Automate this as a scheduled test.', codeSnippet: "-- Step 1: Base backup\npg_basebackup -D /test_recovery/base -Fp -Xs -P\n\n-- Step 2: Create known data state\nINSERT INTO test_table VALUES (1, 'before');\n\n-- Step 3: Mark the restore point\nSELECT pg_create_restore_point('test_recovery_point');\n\n-- Step 4: More changes (to be undone)\nDELETE FROM test_table;  -- oops!\n\n-- Step 5: Recover\n-- Configure recovery_target_name = 'test_recovery_point'\n-- Start from base backup\n\n-- Step 6: Verify\nSELECT * FROM test_table;\n-- Should show (1, 'before')", tags: ['admin', 'pitr', 'testing', 'disaster-recovery'] },
  { id: 'pg-admin-l3-027', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Connection Pooling', question: 'What is server_reset_query in pgBouncer?', options: ['A query to restart pgBouncer', 'A SQL command executed when a server connection is returned to the pool — typically DISCARD ALL to reset session state, ensuring the next client gets a clean connection', 'A query to test server health', 'A query to reset statistics'], correctAnswer: 1, explanation: 'When a connection is returned to the pool (end of transaction in transaction mode), pgBouncer runs server_reset_query to clean up session state. DISCARD ALL resets search_path, temp tables, prepared statements, and all session variables. This prevents state leaking between clients.', codeSnippet: "-- pgbouncer.ini:\nserver_reset_query = DISCARD ALL\n\n-- DISCARD ALL resets:\n-- - Prepared statements\n-- - Temporary tables\n-- - Session variables (SET)\n-- - LISTEN/NOTIFY registrations\n-- - Search path\n\n-- For session mode: can be empty\nserver_reset_query =\n\n-- Custom reset (lighter than DISCARD ALL):\nserver_reset_query = RESET ALL; DEALLOCATE ALL; CLOSE ALL;", tags: ['admin', 'pgbouncer', 'server-reset-query', 'session-state'] },
  { id: 'pg-admin-l3-028', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Streaming Replication', question: 'What is replication lag and how do you monitor it?', options: ['The time delay between primary and standby — measured as the difference in WAL positions or as a time offset using pg_stat_replication on the primary or pg_last_xact_replay_timestamp() on the standby', 'Network latency between servers', 'Disk I/O delay', 'Query execution delay'], correctAnswer: 0, explanation: 'Replication lag is the delay between when a change is committed on the primary and when it is applied on the standby. Monitor on the primary using pg_stat_replication (compare sent_lsn vs replay_lsn). Monitor on the standby using pg_last_xact_replay_timestamp(). High lag may indicate standby I/O bottleneck or network issues.', codeSnippet: "-- On primary: check per-standby lag\nSELECT client_addr, application_name,\n  state, sync_state,\n  pg_wal_lsn_diff(sent_lsn, replay_lsn) AS replay_lag_bytes,\n  replay_lag  -- PG 10+: time-based lag\nFROM pg_stat_replication;\n\n-- On standby: check replay lag\nSELECT now() - pg_last_xact_replay_timestamp() AS replay_lag;\n\n-- Alert if lag exceeds threshold:\n-- If replay_lag > interval '5 seconds' THEN alert", tags: ['admin', 'replication', 'lag', 'monitoring'] },
  { id: 'pg-admin-l3-029', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'WAL Archiving', question: 'What is the difference between archive_mode = on and archive_mode = always?', options: ['They are identical', 'archive_mode = on archives WAL only on the primary; archive_mode = always also archives WAL on standbys — useful for standbys that might be promoted and need their own WAL archive', 'always means continuous archiving', 'on is deprecated'], correctAnswer: 1, explanation: 'archive_mode = on (default) only archives WAL when the server is the primary. archive_mode = always (PostgreSQL 9.5+) archives WAL even on standbys. This is useful because if a standby is promoted, it already has a WAL archive from its standby period, enabling PITR from the new primary.', codeSnippet: "-- Standard (primary only):\narchive_mode = on\narchive_command = 'cp %p /archive/%f'\n-- Only archives when running as primary\n\n-- Also archive on standbys:\narchive_mode = always\narchive_command = 'cp %p /archive/%f'\n-- Archives on both primary and standby\n\n-- Why 'always'?\n-- If standby is promoted, it already has\n-- WAL archive history for PITR\n-- Critical for disaster recovery scenarios", tags: ['admin', 'wal-archiving', 'archive-mode', 'standby'] },
  { id: 'pg-admin-l3-030', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'What happens to the standby.signal and recovery.signal files?', options: ['They persist after recovery', 'standby.signal indicates a server should start as a standby; recovery.signal indicates targeted recovery (PITR) — both are removed automatically when recovery is complete or the server is promoted', 'They must be manually deleted', 'They control replication speed'], correctAnswer: 1, explanation: 'In PostgreSQL 12+, these files replaced the old recovery.conf. standby.signal makes the server a continuously-recovering standby. recovery.signal makes it perform targeted recovery (PITR) and then promote. Both are automatically removed upon completion/promotion. The recovery settings are in postgresql.conf.', codeSnippet: "-- For a standby (continuous recovery):\ntouch /pgdata/standby.signal\n-- postgresql.conf:\nprimary_conninfo = 'host=primary user=repl_user'\nrestore_command = 'cp /archive/%f %p'\n\n-- For PITR (recover and promote):\ntouch /pgdata/recovery.signal\n-- postgresql.conf:\nrestore_command = 'cp /archive/%f %p'\nrecovery_target_time = '2024-06-15 14:30:00'\nrecovery_target_action = 'promote'\n\n-- Files are removed automatically after:\n-- - standby: promotion (pg_promote())\n-- - recovery: reaching target and promoting", tags: ['admin', 'pitr', 'signal-files', 'standby'] },
  { id: 'pg-admin-l3-031', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Streaming Replication', question: 'What is max_standby_streaming_delay?', options: ['Maximum delay before standby disconnects', 'Controls how long a standby waits before cancelling queries that conflict with WAL replay — balances between keeping standby queries alive and minimizing replication lag', 'Maximum streaming bandwidth', 'Maximum number of standby connections'], correctAnswer: 1, explanation: 'When WAL replay needs to clean up dead tuples or modify data that an active query on the standby is reading, there is a conflict. max_standby_streaming_delay controls how long the standby waits before cancelling the conflicting query. Higher values favor query completion; lower values favor replication timeliness.', codeSnippet: "-- On standby: postgresql.conf\nmax_standby_streaming_delay = 30s  -- default\n\n-- -1 = wait indefinitely (queries never cancelled)\nmax_standby_streaming_delay = -1\n-- Risk: replication lag grows during long queries\n\n-- 0 = cancel immediately\nmax_standby_streaming_delay = 0\n-- No query interference with replay\n\n-- Better alternative: use hot_standby_feedback\nhot_standby_feedback = on\n-- Tells primary about standby queries, preventing\n-- vacuum from removing needed tuples", tags: ['admin', 'replication', 'standby-delay', 'conflict-resolution'] },
  { id: 'pg-admin-l3-032', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Connection Pooling', question: 'What is the application_name_add_host setting in pgBouncer?', options: ['Adds the host to the application name', 'When enabled, pgBouncer appends the client IP and port to the application_name — making it visible in pg_stat_activity for identifying which client is running which query', 'Adds the server hostname', 'Names the pgBouncer application'], correctAnswer: 1, explanation: 'With connection pooling, all queries in pg_stat_activity appear to come from pgBouncer, making it hard to identify the actual client. application_name_add_host appends the client address to application_name, enabling client identification in monitoring and troubleshooting.', codeSnippet: "-- pgbouncer.ini:\napplication_name_add_host = 1\n\n-- Result in pg_stat_activity:\n-- application_name = 'myapp - 192.168.1.50:43210'\n\n-- Without this setting:\n-- application_name = 'myapp'\n-- (no way to know which client)\n\n-- Monitor with client info:\nSELECT application_name, query, state\nFROM pg_stat_activity\nWHERE datname = 'mydb';", tags: ['admin', 'pgbouncer', 'monitoring', 'application-name'] },
  { id: 'pg-admin-l3-033', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'WAL Archiving', question: 'How do you estimate WAL generation rate?', options: ['Check file system growth', 'Query pg_stat_wal (PG 14+) or track pg_current_wal_lsn() over time — the rate helps size archive storage, plan backup frequency, and set replication bandwidth requirements', 'Use pg_stat_activity', 'Count WAL files'], correctAnswer: 1, explanation: 'Knowing WAL generation rate is critical for capacity planning: archive storage sizing, network bandwidth for replication, and backup strategy. Use pg_stat_wal.wal_bytes (PG 14+), or sample pg_current_wal_lsn() at intervals and calculate the difference.', codeSnippet: "-- PG 14+: cumulative WAL stats\nSELECT pg_size_pretty(wal_bytes) AS total_wal_generated,\n  stats_reset\nFROM pg_stat_wal;\n\n-- Calculate rate from two samples:\n-- Sample 1:\nSELECT pg_current_wal_lsn() AS lsn1;  -- 0/A000000\n-- Wait 1 hour...\n-- Sample 2:\nSELECT pg_current_wal_lsn() AS lsn2;  -- 0/F000000\n\nSELECT pg_size_pretty(\n  pg_wal_lsn_diff('0/F000000', '0/A000000')\n) AS wal_per_hour;\n-- Result: ~80 MB/hour\n\n-- Count WAL files in pg_wal:\n-- ls -la pg_wal/ | wc -l", tags: ['admin', 'wal-archiving', 'wal-rate', 'capacity-planning'] },
  { id: 'pg-admin-l3-034', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'What is the role of pg_wal_replay_pause() and pg_wal_replay_resume()?', options: ['Pause and resume WAL generation', 'Pause and resume WAL replay on a standby server — useful for inspecting standby data at a specific point or creating a consistent snapshot without stopping the server', 'Pause and resume archiving', 'Pause and resume replication slots'], correctAnswer: 1, explanation: 'On a standby, pg_wal_replay_pause() stops WAL replay while still receiving WAL from the primary. The standby data freezes at the current replay point. This is useful for taking consistent backups from the standby or inspecting data at a point in time. pg_wal_replay_resume() continues replay.', codeSnippet: "-- On standby: pause replay\nSELECT pg_wal_replay_pause();\n\n-- Check status:\nSELECT pg_is_wal_replay_paused();  -- true\n\n-- Data is now frozen at current replay point\n-- Take a backup, run queries, inspect data...\n\n-- Resume replay:\nSELECT pg_wal_replay_resume();\n\n-- Note: WAL is still received while paused\n-- It accumulates and replays when resumed\n-- Monitor: pg_stat_replication shows growing lag", tags: ['admin', 'pitr', 'wal-replay', 'pause-resume'] },
  { id: 'pg-admin-l3-035', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Streaming Replication', question: 'What is hot_standby_feedback?', options: ['Temperature monitoring for standbys', 'A setting that makes the standby report its active queries to the primary — preventing the primary from vacuuming rows that standby queries might still need, at the cost of potentially increased bloat on the primary', 'Feedback about standby performance', 'A rating system for standbys'], correctAnswer: 1, explanation: 'With hot_standby_feedback = on, the standby periodically sends its oldest active transaction ID (xmin) to the primary. The primary considers this when vacuuming, preventing removal of tuples the standby needs. This eliminates query cancellations on the standby but may increase bloat on the primary if standby runs long queries.', codeSnippet: "-- On standby: postgresql.conf\nhot_standby_feedback = on\n\n-- Tradeoff:\n-- ON:  No query cancellations on standby\n--      Primary may accumulate more dead tuples\n-- OFF: Long standby queries may be cancelled\n--      Primary vacuums normally\n\n-- Check feedback from primary:\nSELECT client_addr, backend_xmin\nFROM pg_stat_replication;\n-- backend_xmin shows standby's xmin horizon\n-- NULL = no feedback (hot_standby_feedback = off)", tags: ['admin', 'replication', 'hot-standby-feedback', 'query-conflicts'] },
  { id: 'pg-admin-l3-036', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Connection Pooling', question: 'What is server_check_query in pgBouncer?', options: ['A query to check server version', 'A SQL query that pgBouncer runs to verify a database connection is still alive before handing it to a client — default is SELECT 1', 'A query to check pool sizes', 'A health check for clients'], correctAnswer: 1, explanation: 'server_check_query is executed when a pooled connection is about to be given to a client (if server_check_delay has elapsed). It verifies the connection is still valid. The default SELECT 1 is lightweight. If the check fails, the connection is discarded and a new one is created.', codeSnippet: "-- pgbouncer.ini:\nserver_check_query = SELECT 1\nserver_check_delay = 30  -- seconds between checks\n\n-- Disable check (slightly faster, risk stale connections):\nserver_check_query = ;\nserver_check_delay = 0\n\n-- Custom health check:\nserver_check_query = SELECT 1 FROM pg_stat_activity LIMIT 1\n\n-- For PG 14+ (faster, no round-trip):\nserver_check_query = ;  -- disable, use server_fast_close", tags: ['admin', 'pgbouncer', 'health-check', 'connection-validation'] },
  { id: 'pg-admin-l3-037', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Streaming Replication', question: 'What is pg_rewind and when is it used?', options: ['Rewinds queries to their start', 'A tool that synchronizes a diverged server (old primary) to a new timeline — faster than rebuilding from scratch because it only copies changed pages', 'Rewinds WAL to a checkpoint', 'Undoes the last transaction'], correctAnswer: 1, explanation: 'After failover, the old primary has diverged from the new primary (different timeline). pg_rewind identifies data pages that differ and copies only those from the new primary, making the old primary consistent with the new timeline. It can then be started as a standby. Much faster than a full pg_basebackup rebuild.', codeSnippet: "-- After failover: make old primary a standby\n\n-- Step 1: Stop old primary\npg_ctl stop -D /old_primary/data\n\n-- Step 2: Rewind to new primary's timeline\npg_rewind --target-pgdata=/old_primary/data \\\n  --source-server='host=new_primary port=5432 user=repl_user'\n\n-- Step 3: Configure as standby\ntouch /old_primary/data/standby.signal\n# Update primary_conninfo to point to new primary\n\n-- Step 4: Start as standby\npg_ctl start -D /old_primary/data\n\n-- Requires: wal_log_hints = on or data checksums", tags: ['admin', 'replication', 'pg-rewind', 'failover'] },
  { id: 'pg-admin-l3-038', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'WAL Archiving', question: 'What is wal_keep_size (previously wal_keep_segments)?', options: ['Maximum WAL file size', 'Minimum amount of WAL files retained in pg_wal — provides a safety margin for standbys to catch up without relying solely on WAL archiving; renamed from wal_keep_segments in PG 13', 'WAL compression ratio', 'Size of WAL buffer'], correctAnswer: 1, explanation: 'wal_keep_size (PG 13+, previously wal_keep_segments) tells PostgreSQL to keep at least this much WAL in pg_wal even if it has been archived or consumed by all standbys. This provides a buffer for standbys that temporarily disconnect. Replication slots provide a more reliable mechanism but wal_keep_size is a simpler safety net.', codeSnippet: "-- Keep at least 1GB of WAL:\nwal_keep_size = 1GB  -- PG 13+\n\n-- Old syntax (PG 12 and earlier):\n-- wal_keep_segments = 64  -- 64 * 16MB = 1GB\n\n-- wal_keep_size vs replication slots:\n-- wal_keep_size: fixed amount, no per-standby tracking\n-- Replication slots: per-standby, but risk disk fill\n\n-- Use both for safety:\nwal_keep_size = 2GB  -- general safety net\n-- Plus replication slots for each standby", tags: ['admin', 'wal-archiving', 'wal-keep-size', 'retention'] },
  { id: 'pg-admin-l3-039', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Connection Pooling', question: 'How do you handle authentication with pgBouncer?', options: ['pgBouncer uses its own user database', 'pgBouncer can use an auth_file (userlist.txt) with username/password pairs, auth_query to look up passwords from the database, or passthrough authentication to delegate to PostgreSQL', 'Authentication is not needed with pgBouncer', 'pgBouncer only supports trust authentication'], correctAnswer: 1, explanation: 'pgBouncer authentication options: (1) auth_file with hashed passwords, (2) auth_query that queries a function in PostgreSQL to verify credentials dynamically, (3) auth_type=hba to use a pgBouncer HBA file, (4) cert for certificate authentication. auth_query is most convenient as it syncs with PostgreSQL passwords.', codeSnippet: "-- pgbouncer.ini:\nauth_type = scram-sha-256\nauth_file = /etc/pgbouncer/userlist.txt\n\n-- userlist.txt format:\n-- \"username\" \"password_hash\"\n\n-- Better: use auth_query (dynamic password lookup)\nauth_type = scram-sha-256\nauth_query = SELECT usename, passwd FROM pg_shadow WHERE usename=$1\n-- Requires a user that can read pg_shadow\n\n-- Or use auth_user for passthrough:\nauth_user = pgbouncer_auth\nauth_query = SELECT usename, passwd FROM pg_shadow WHERE usename=$1", tags: ['admin', 'pgbouncer', 'authentication'] },
  { id: 'pg-admin-l3-040', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Streaming Replication', question: 'What is the quorum-based synchronous replication?', options: ['Requires all standbys to confirm', 'Uses FIRST or ANY syntax in synchronous_standby_names — ANY N requires confirmation from any N standbys out of the list, providing both data safety and higher availability than requiring specific standbys', 'Only one standby can be synchronous', 'Quorum voting for failover'], correctAnswer: 1, explanation: 'ANY N (standby1, standby2, standby3) means the primary waits for confirmation from any N standbys. ANY 2 out of 3 standbys provides high availability (1 can be down) while ensuring data durability (2 copies). FIRST N waits for the first N standbys in priority order.', codeSnippet: "-- Quorum: any 2 of 3 standbys must confirm\nsynchronous_standby_names = 'ANY 2 (standby1, standby2, standby3)'\n\n-- Priority: first 2 in order\nsynchronous_standby_names = 'FIRST 2 (standby1, standby2, standby3)'\n\n-- Single synchronous standby:\nsynchronous_standby_names = 'standby1'\n\n-- Check sync status:\nSELECT application_name, sync_state, sync_priority\nFROM pg_stat_replication;\n-- sync_state: sync, potential, async, quorum", tags: ['admin', 'replication', 'synchronous', 'quorum'] },
  { id: 'pg-admin-l3-041', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'How do you handle tablespace paths during PITR to a different server?', options: ['Tablespaces are automatically adjusted', 'Create matching directories on the recovery server, or use tablespace_map to remap tablespace locations during recovery', 'Tablespaces are not restored during PITR', 'You must use the same server'], correctAnswer: 1, explanation: 'When restoring to a different server, tablespace directory paths may differ. pg_basebackup includes a tablespace_map file that can be edited to remap paths. Alternatively, create the same directories on the recovery server, or use --tablespace-mapping (-T) with pg_basebackup.', codeSnippet: "# pg_basebackup with tablespace remapping:\npg_basebackup -h primary -D /recovery/data \\\n  -T /ssd/pgdata=/recovery_ssd/pgdata \\\n  -T /hdd/pgdata=/recovery_hdd/pgdata\n\n# Or edit tablespace_map after backup:\n# /recovery/data/tablespace_map:\n# 12345 /recovery_ssd/pgdata\n# 12346 /recovery_hdd/pgdata\n\n# Ensure directories exist and are owned by postgres:\nmkdir -p /recovery_ssd/pgdata\nchown postgres:postgres /recovery_ssd/pgdata", tags: ['admin', 'pitr', 'tablespaces', 'remapping'] },
  { id: 'pg-admin-l3-042', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Connection Pooling', question: 'What is the query_wait_timeout setting in pgBouncer?', options: ['Maximum query execution time', 'Maximum time a client query can wait in the queue for a server connection — if no connection becomes available within this time, the client query is cancelled with an error', 'Timeout between queries', 'Server response timeout'], correctAnswer: 1, explanation: 'query_wait_timeout (default 120s) limits how long a client waits in the queue. If all pool connections are busy and no connection becomes available within this time, the client receives an error. This prevents unbounded queuing and provides back-pressure to applications when the database is overloaded.', codeSnippet: "-- pgbouncer.ini:\nquery_wait_timeout = 120  -- seconds (default)\n\n-- Short timeout for latency-sensitive apps:\nquery_wait_timeout = 10\n\n-- Long timeout for batch processing:\nquery_wait_timeout = 600\n\n-- Disable timeout (wait forever):\nquery_wait_timeout = 0\n\n-- Related timeouts:\nclient_idle_timeout = 0     -- idle client disconnect\nserver_idle_timeout = 600   -- idle server disconnect\nclient_login_timeout = 60   -- login timeout", tags: ['admin', 'pgbouncer', 'timeout', 'queue'] },
  { id: 'pg-admin-l3-043', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Streaming Replication', question: 'What is wal_sender_timeout?', options: ['Maximum time for WAL generation', 'Maximum time a WAL sender waits for a standby acknowledgment before terminating the replication connection — prevents keeping connections to unresponsive standbys', 'WAL segment timeout', 'Time to send one WAL record'], correctAnswer: 1, explanation: 'wal_sender_timeout (default 60s) terminates replication connections to standbys that have not responded within the specified time. This detects network failures and unresponsive standbys. The standby has a corresponding wal_receiver_timeout. Both should be set to similar values.', codeSnippet: "-- On primary:\nwal_sender_timeout = 60s  -- default\n\n-- On standby:\nwal_receiver_timeout = 60s  -- default\n\n-- For high-latency WAN replication:\nwal_sender_timeout = 120s\nwal_receiver_timeout = 120s\n\n-- Disable (not recommended):\nwal_sender_timeout = 0\n\n-- Monitor sender status:\nSELECT pid, application_name, state, reply_time\nFROM pg_stat_replication;", tags: ['admin', 'replication', 'wal-sender-timeout', 'network'] },
  { id: 'pg-admin-l3-044', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'WAL Archiving', question: 'What is pg_receivewal and when is it used?', options: ['A tool to receive WAL on standbys', 'A utility that streams WAL segments from a running server and saves them to a directory — provides continuous WAL archiving without requiring archive_command on the primary', 'A WAL analysis tool', 'A WAL compression utility'], correctAnswer: 1, explanation: 'pg_receivewal connects to a server as a replication client and saves WAL segments to a local directory. Unlike archive_command (push model), pg_receivewal pulls WAL continuously. It supports slot-based WAL retention and can compress segments. Useful when archive_command is not feasible or reliable.', codeSnippet: "# Stream WAL to local directory:\npg_receivewal -h primary -U repl_user -D /archive/wal \\\n  --slot=wal_receiver_slot -v\n\n# With compression:\npg_receivewal -h primary -U repl_user -D /archive/wal \\\n  --compress=gzip --slot=wal_receiver_slot\n\n# Create the slot first:\npsql -h primary -c \\\n  \"SELECT pg_create_physical_replication_slot('wal_receiver_slot');\"\n\n# Runs continuously as a daemon\n# Provides lower latency than archive_command", tags: ['admin', 'wal-archiving', 'pg-receivewal', 'continuous-archiving'] },
  { id: 'pg-admin-l3-045', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'What is the difference between recovery.signal and standby.signal?', options: ['They are the same', 'recovery.signal triggers targeted recovery (PITR) that ends when the target is reached; standby.signal keeps the server in continuous recovery as a standby, never promoting automatically', 'recovery.signal is for standbys', 'standby.signal is for PITR'], correctAnswer: 1, explanation: 'recovery.signal: the server recovers from WAL until the recovery target is reached, then performs recovery_target_action (promote/pause/shutdown). standby.signal: the server continuously recovers WAL and remains a read-only standby indefinitely. You use one or the other, never both.', codeSnippet: "-- For PITR (recover and stop):\ntouch /pgdata/recovery.signal\n-- postgresql.conf:\nrestore_command = 'cp /archive/%f %p'\nrecovery_target_time = '2024-06-15 14:30:00'\nrecovery_target_action = 'promote'\n\n-- For standby (continuous recovery):\ntouch /pgdata/standby.signal\n-- postgresql.conf:\nprimary_conninfo = 'host=primary user=repl_user'\nrestore_command = 'cp /archive/%f %p'  -- optional fallback\n\n-- Never create both files simultaneously!", tags: ['admin', 'pitr', 'recovery-signal', 'standby-signal'] },
  { id: 'pg-admin-l3-046', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Streaming Replication', question: 'How do you handle replication conflicts on a hot standby?', options: ['Conflicts cannot occur on standbys', 'Conflicts arise when WAL replay needs to modify data being read by standby queries — resolve with hot_standby_feedback, max_standby_streaming_delay, or vacuum_defer_cleanup_age on the primary', 'Cancel all standby queries', 'Disable hot standby'], correctAnswer: 1, explanation: 'Replication conflicts occur when: vacuum on primary removes tuples a standby query needs, exclusive locks in WAL conflict with standby queries, or tablespace/database drops conflict with standby connections. Solutions: hot_standby_feedback (prevents vacuum conflicts), max_standby_streaming_delay (time window), or running long queries on a delayed replica.', codeSnippet: "-- Solution 1: hot_standby_feedback (on standby)\nhot_standby_feedback = on\n-- Primary considers standby xmin, prevents vacuuming needed tuples\n\n-- Solution 2: Allow more delay (on standby)\nmax_standby_streaming_delay = 300s  -- 5 minutes\n\n-- Solution 3: Defer cleanup on primary\nvacuum_defer_cleanup_age = 1000  -- keep 1000 extra transactions\n\n-- Monitor conflicts on standby:\nSELECT datname, confl_tablespace, confl_lock,\n  confl_snapshot, confl_bufferpin, confl_deadlock\nFROM pg_stat_database_conflicts;", tags: ['admin', 'replication', 'conflicts', 'hot-standby'] },
  { id: 'pg-admin-l3-047', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Connection Pooling', question: 'What happens when pgBouncer process dies?', options: ['All connections continue normally', 'All client connections are dropped because pgBouncer is the intermediary — use a process supervisor (systemd, supervisord) to auto-restart pgBouncer, and consider running multiple pgBouncer instances behind a load balancer', 'PostgreSQL handles the connections', 'Nothing, connections auto-recover'], correctAnswer: 1, explanation: 'pgBouncer is a single point of failure for all pooled connections. If it dies, all clients are disconnected. Mitigation: (1) run under systemd with Restart=always, (2) use multiple pgBouncer instances behind HAProxy/keepalived for high availability, (3) use pgBouncer SO_REUSEPORT for seamless restarts.', codeSnippet: "# systemd service for auto-restart:\n# [Service]\n# ExecStart=/usr/bin/pgbouncer /etc/pgbouncer/pgbouncer.ini\n# Restart=always\n# RestartSec=5\n\n# High availability: two pgBouncers behind keepalived\n# pgBouncer 1 (active):  10.0.0.1:6432\n# pgBouncer 2 (standby): 10.0.0.2:6432\n# VIP: 10.0.0.100:6432\n\n# pgBouncer online restart (since 1.18):\n# SO_REUSEPORT allows new process to take over\npgbouncer -R /etc/pgbouncer/pgbouncer.ini", tags: ['admin', 'pgbouncer', 'high-availability', 'failover'] },
  { id: 'pg-admin-l3-048', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Streaming Replication', question: 'What is a delayed standby and when is it useful?', options: ['A standby that is slow due to hardware', 'A standby intentionally configured to replay WAL with a time delay — provides a window to recover from accidental data deletion or corruption by querying the delayed standby before the mistake is replayed', 'A standby in a different timezone', 'A standby that uses slower storage'], correctAnswer: 1, explanation: 'recovery_min_apply_delay creates a standby that is intentionally behind the primary by a configured time. If someone accidentally drops a table or deletes data, you have a time window to query the delayed standby for the original data before the destructive operation is replayed.', codeSnippet: "-- On delayed standby: postgresql.conf\nrecovery_min_apply_delay = '1 hour'\n\n-- The standby receives WAL in real-time but delays replay\n-- If someone drops a table at 14:00:\n-- At 14:30: standby still has the table (from 13:30)\n-- At 14:59: last chance to query before replay\n-- At 15:00: DROP is replayed, table gone\n\n-- Recovery procedure:\n-- 1. Pause replay on delayed standby\nSELECT pg_wal_replay_pause();\n-- 2. Query/export the needed data\npg_dump -t dropped_table -h delayed_standby mydb\n-- 3. Restore data to primary\npsql -h primary mydb < dropped_table.sql\n-- 4. Resume replay\nSELECT pg_wal_replay_resume();", tags: ['admin', 'replication', 'delayed-standby', 'disaster-recovery'] },
  { id: 'pg-admin-l3-049', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'WAL Archiving', question: 'What is the archive_library setting (PostgreSQL 15+)?', options: ['A WAL compression library', 'An alternative to archive_command that uses a shared library module for WAL archiving — avoids fork/exec overhead per WAL segment and enables built-in archiving implementations', 'A library for reading archived WAL', 'A backup library path'], correctAnswer: 1, explanation: 'archive_library (PG 15+) specifies a shared library for WAL archiving, replacing the archive_command shell execution. This is more efficient (no fork/exec per segment) and enables purpose-built archiving modules. The built-in basic_archive module archives to a local directory without shell overhead.', codeSnippet: "-- Traditional: shell command per segment\narchive_command = 'cp %p /archive/%f'\n\n-- PG 15+: use built-in archive module\narchive_library = 'basic_archive'\nbasic_archive.archive_directory = '/archive/wal'\n\n-- Advantages of archive_library:\n-- No fork/exec per WAL segment\n-- More reliable (library vs shell)\n-- Custom modules possible (e.g., S3, GCS)\n\n-- Note: archive_command is still used when\n-- archive_library is empty string (default)", tags: ['admin', 'wal-archiving', 'archive-library', 'performance'] },
  { id: 'pg-admin-l3-050', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'What is the purpose of recovery_target_inclusive?', options: ['Controls whether to include all tables in recovery', 'Controls whether the recovery target (time, XID, or LSN) itself is included in the recovery — TRUE (default) stops just after the target; FALSE stops just before it', 'Controls whether recovery includes indexes', 'Controls whether recovery includes large objects'], correctAnswer: 1, explanation: 'recovery_target_inclusive = true (default) means the recovery includes the target transaction/timestamp. FALSE stops just before the target. This is important for precision: if recovering to undo a specific transaction, use FALSE with recovery_target_xid to stop before that transaction was committed.', codeSnippet: "-- Include the target transaction:\nrecovery_target_xid = '12345'\nrecovery_target_inclusive = true\n-- Recovers UP TO AND INCLUDING transaction 12345\n\n-- Exclude the target (stop before):\nrecovery_target_xid = '12345'\nrecovery_target_inclusive = false\n-- Recovers UP TO BUT NOT INCLUDING transaction 12345\n\n-- For timestamp targets:\nrecovery_target_time = '2024-06-15 14:30:00'\nrecovery_target_inclusive = false\n-- Stops just before 14:30:00", tags: ['admin', 'pitr', 'recovery-target-inclusive'] },
  { id: 'pg-admin-l3-051', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Streaming Replication', question: 'What are the key checkpoints settings and how do they affect replication?', options: ['Checkpoints are irrelevant to replication', 'checkpoint_timeout and max_wal_size control how often checkpoints occur — more frequent checkpoints reduce recovery time but increase I/O; less frequent ones reduce I/O but increase recovery time and WAL accumulation', 'Checkpoints control replication speed', 'Only checkpoint_timeout matters'], correctAnswer: 1, explanation: 'Checkpoints flush dirty buffers to disk. checkpoint_timeout (default 5min) and max_wal_size (default 1GB) control frequency. More frequent checkpoints mean: faster crash recovery, less WAL to retain, but more I/O. For replication, checkpoints on the primary trigger restartpoints on standbys. checkpoint_completion_target spreads I/O.', codeSnippet: "-- Key checkpoint settings:\ncheckpoint_timeout = 5min       -- max time between checkpoints\nmax_wal_size = 1GB              -- WAL before triggering checkpoint\nmin_wal_size = 80MB             -- keep at least this much WAL\ncheckpoint_completion_target = 0.9  -- spread I/O over 90% of interval\n\n-- Monitor checkpoints:\nSELECT checkpoints_timed, checkpoints_req,\n  checkpoint_write_time, checkpoint_sync_time\nFROM pg_stat_bgwriter;\n\n-- High checkpoints_req = checkpoints forced by max_wal_size\n-- Solution: increase max_wal_size", tags: ['admin', 'replication', 'checkpoints', 'wal-size'] },
  { id: 'pg-admin-l3-052', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Connection Pooling', question: 'What is the max_db_connections setting in pgBouncer?', options: ['Same as max_connections in PostgreSQL', 'Limits the total number of server connections per database across all pools — prevents a single database from consuming all available PostgreSQL connections', 'Maximum database count', 'Maximum client connections per database'], correctAnswer: 1, explanation: 'max_db_connections limits server connections per database (across all users/pools). This prevents a single database from monopolizing max_connections. Combined with default_pool_size (per pool) and max_client_conn (total client connections), it provides fine-grained connection control.', codeSnippet: "-- pgbouncer.ini:\nmax_db_connections = 50    -- max server connections per DB\nmax_user_connections = 30  -- max server connections per user\ndefault_pool_size = 20     -- connections per user/db pool\nmax_client_conn = 1000     -- total client connections\n\n-- Example: 3 databases, max_connections=100\n-- max_db_connections = 30 each\n-- Ensures no single DB uses all 100 connections\n\n-- 0 = unlimited (constrained by max_connections only)\nmax_db_connections = 0", tags: ['admin', 'pgbouncer', 'connection-limits'] },
  { id: 'pg-admin-l3-053', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Streaming Replication', question: 'How do you set up replication with pg_basebackup -R flag?', options: ['It does nothing special', 'The -R flag automatically creates standby.signal and configures primary_conninfo in postgresql.auto.conf — making the backup immediately usable as a streaming replication standby', 'It creates a read-only backup', 'It enables compression during backup'], correctAnswer: 1, explanation: 'pg_basebackup -R (--write-recovery-conf) creates standby.signal file and writes primary_conninfo to postgresql.auto.conf with the connection string used during backup. This means you can start the backup directory as a standby immediately without manual configuration.', codeSnippet: "# One-command standby creation:\npg_basebackup -h primary -U repl_user \\\n  -D /standby/data -Fp -Xs -P -R\n\n# Creates:\n# /standby/data/standby.signal\n# /standby/data/postgresql.auto.conf with:\n#   primary_conninfo = 'host=primary user=repl_user ...'\n\n# Just start the standby:\npg_ctl start -D /standby/data\n# It's now replicating!\n\n# Optional: add slot-based replication\n# Edit postgresql.auto.conf:\n# primary_slot_name = 'standby1_slot'", tags: ['admin', 'replication', 'pg-basebackup', 'standby-setup'] },
  { id: 'pg-admin-l3-054', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'WAL Archiving', question: 'How do you set up WAL archiving to a remote server?', options: ['PostgreSQL does not support remote archiving', 'Use archive_command with tools like rsync, scp, aws s3 cp, or dedicated backup tools (pgBackRest, Barman) — the command must return 0 on success and non-zero on failure', 'Configure remote_archive_host in postgresql.conf', 'Use streaming replication instead'], correctAnswer: 1, explanation: 'archive_command can use any shell command that returns 0 on success. Common approaches: rsync for remote servers, aws/gcloud CLI for cloud storage, or dedicated tools like pgBackRest (handles compression, encryption, parallel transfer). The command must be idempotent (safe to retry).', codeSnippet: "-- rsync to remote server:\narchive_command = 'rsync -a %p backup_server:/archive/wal/%f'\n\n-- scp (simpler but less efficient):\narchive_command = 'scp %p backup_server:/archive/wal/%f'\n\n-- AWS S3:\narchive_command = 'aws s3 cp %p s3://my-bucket/wal/%f --sse'\n\n-- Google Cloud Storage:\narchive_command = 'gsutil cp %p gs://my-bucket/wal/%f'\n\n-- pgBackRest (recommended for production):\narchive_command = 'pgbackrest --stanza=mydb archive-push %p'\n\n-- Important: command must be idempotent!\n-- (safe to run multiple times for same file)", tags: ['admin', 'wal-archiving', 'remote', 'cloud-storage'] },
  { id: 'pg-admin-l3-055', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'What is pg_waldump and how is it useful for PITR?', options: ['Dumps the WAL archive', 'A tool that reads and displays WAL records in human-readable format — useful for analyzing what changes occurred at specific LSN positions or time ranges during incident investigation', 'Creates WAL backups', 'Validates WAL integrity'], correctAnswer: 1, explanation: 'pg_waldump (previously pg_xlogdump) decodes WAL segments into human-readable records showing the resource manager, transaction ID, type of change, and affected relation/block. This is invaluable for: identifying when a problematic change occurred, choosing a precise recovery target, and understanding WAL contents.', codeSnippet: "# Decode WAL records in a segment:\npg_waldump 00000001000000000000001A\n\n# Filter by time range:\npg_waldump --start='2024-06-15 14:00:00' \\\n  --end='2024-06-15 14:30:00' \\\n  /var/lib/postgresql/data/pg_wal/00000001000000000000001A\n\n# Filter by relation (table OID):\npg_waldump --relation=16384 000000010000000000000001\n\n# Output shows:\n# rmgr: Heap  len: 54 tx: 12345 lsn: 0/1A000028\n#   desc: DELETE off 5 KEYS_UPDATED\n#   blkref #0: rel 1663/16384/16385 blk 42", tags: ['admin', 'pitr', 'pg-waldump', 'wal-analysis'] },
  { id: 'pg-admin-l3-056', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Connection Pooling', question: 'What is the difference between pgBouncer and PgPool-II?', options: ['They are identical', 'pgBouncer is a lightweight single-purpose connection pooler; PgPool-II is a multi-feature middleware that includes connection pooling, load balancing, automatic failover, and query caching — PgPool-II is more complex but offers more features', 'pgBouncer is newer', 'PgPool-II is deprecated'], correctAnswer: 1, explanation: 'pgBouncer: single-purpose, lightweight, supports only connection pooling. PgPool-II: full-featured middleware with connection pooling, read query load balancing, automatic failover, online recovery, and in-memory query caching. pgBouncer is preferred for pure pooling; PgPool-II when you need integrated HA/load balancing.', codeSnippet: "-- pgBouncer: pure connection pooling\n-- Lightweight, ~2MB memory\n-- Single-threaded (very efficient)\n-- No query routing or caching\n\n-- PgPool-II: middleware suite\n-- Connection pooling\n-- Read query load balancing:\n--   SELECT -> standby, INSERT/UPDATE/DELETE -> primary\n-- Automatic failover\n-- In-memory query caching\n-- Watchdog for PgPool-II HA\n\n-- Typical production setup:\n-- pgBouncer + custom failover (Patroni, pg_auto_failover)\n-- OR\n-- PgPool-II for all-in-one solution", tags: ['admin', 'pgbouncer', 'pgpool', 'comparison'] },
  { id: 'pg-admin-l3-057', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Streaming Replication', question: 'What is pg_stat_wal_receiver?', options: ['A WAL file count view', 'A view on the standby that shows the status of the WAL receiver process — including connection info, last received/flushed/replayed LSN positions, and the current receiver state', 'A view for WAL sender statistics', 'A monitoring tool for WAL archiving'], correctAnswer: 1, explanation: 'pg_stat_wal_receiver runs on the standby and shows: status (streaming/stopped), receive_start_lsn, received_lsn, last_msg_send_time, last_msg_receipt_time, and conninfo. It is the standby-side counterpart to pg_stat_replication on the primary.', codeSnippet: "-- On standby: check WAL receiver status\nSELECT status,\n  receive_start_lsn, received_lsn,\n  last_msg_send_time, last_msg_receipt_time,\n  slot_name, sender_host, sender_port,\n  conninfo\nFROM pg_stat_wal_receiver;\n\n-- Check if standby is receiving WAL:\n-- status = 'streaming' -> healthy\n-- status = 'stopped' or no rows -> problem\n\n-- Calculate receive lag:\nSELECT now() - last_msg_receipt_time AS receive_lag\nFROM pg_stat_wal_receiver;", tags: ['admin', 'replication', 'wal-receiver', 'standby-monitoring'] },
  { id: 'pg-admin-l3-058', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'WAL Archiving', question: 'What are the best practices for WAL archive storage?', options: ['Store on the same disk as PostgreSQL data', 'Use separate storage from the PostgreSQL data directory, implement redundancy (RAID, replication), monitor free space, set up retention policies, and test restore regularly', 'Only use local SSDs', 'Archive to /tmp'], correctAnswer: 1, explanation: 'WAL archive best practices: (1) separate storage from data directory (different disk/server), (2) redundant storage (S3, GCS, or replicated NFS), (3) monitoring (space usage, archive failures), (4) retention policy (delete old archives), (5) compression to save space, (6) regular restore testing.', codeSnippet: "-- Production archive_command with compression:\narchive_command = 'gzip < %p > /archive/wal/%f.gz'\n\n-- Monitor archive storage:\n-- Check free space on archive disk\n-- Alert when < 20% free\n\n-- Retention: keep 7 days of WAL\n-- (run via cron)\n-- find /archive/wal -name '*.gz' -mtime +7 -delete\n\n-- Or use pgBackRest for managed archiving:\narchive_command = 'pgbackrest --stanza=mydb archive-push %p'\n-- pgBackRest handles compression, encryption,\n-- parallel transfer, and retention automatically", tags: ['admin', 'wal-archiving', 'best-practices', 'storage'] },
  { id: 'pg-admin-l3-059', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'What is the role of backup_label file in base backups?', options: ['A label for organizing backups', 'A file created by pg_basebackup (or pg_backup_start) that records the backup start LSN and timeline — PostgreSQL uses it during recovery to know where to start replaying WAL', 'A file containing backup metadata', 'A label for the backup tool to use'], correctAnswer: 1, explanation: 'backup_label is created at the start of a base backup and included in the backup. It contains: START WAL LOCATION, CHECKPOINT LOCATION, BACKUP METHOD, and START TIME. During recovery, PostgreSQL reads this file to determine the correct WAL replay starting point. The file is removed after recovery completes.', codeSnippet: "-- backup_label contents (example):\n-- START WAL LOCATION: 0/2000028 (file 000000010000000000000002)\n-- CHECKPOINT LOCATION: 0/2000060\n-- BACKUP METHOD: streamed\n-- BACKUP FROM: primary\n-- START TIME: 2024-06-15 10:00:00 UTC\n-- LABEL: pg_basebackup base backup\n-- START TIMELINE: 1\n\n-- Created automatically by pg_basebackup\n-- Or manually with:\nSELECT pg_backup_start('my_backup', fast := true);\n-- ... copy files ...\nSELECT pg_backup_stop();  -- returns backup_label content", tags: ['admin', 'pitr', 'backup-label', 'base-backup'] },
  { id: 'pg-admin-l3-060', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Connection Pooling', question: 'How do you configure pgBouncer for multiple databases?', options: ['Run separate pgBouncer instances', 'Define multiple database entries in the [databases] section of pgbouncer.ini — each can have different connection parameters, pool sizes, and target PostgreSQL servers', 'pgBouncer only supports one database', 'Use database aliases only'], correctAnswer: 1, explanation: 'The [databases] section maps client-facing database names to backend PostgreSQL connections. Each entry can specify different hosts, ports, database names, default users, and pool sizes. You can also use * as a wildcard to proxy any database name.', codeSnippet: "-- pgbouncer.ini:\n[databases]\n-- Direct mapping:\nmydb = host=db1.example.com port=5432 dbname=mydb\n\n-- Read replica for read-only workloads:\nmydb_ro = host=replica1 port=5432 dbname=mydb\n\n-- Different pool size for specific database:\nanalytics = host=db2 port=5432 dbname=analytics pool_size=5\n\n-- Wildcard: proxy any database name:\n* = host=db1.example.com port=5432\n\n-- Forced user:\nadmin_db = host=db1 dbname=postgres force_user=admin", tags: ['admin', 'pgbouncer', 'multi-database', 'configuration'] },
  { id: 'pg-admin-l3-061', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Streaming Replication', question: 'What is the recovery_min_apply_delay setting?', options: ['Minimum time between applying WAL records', 'Configures a deliberate delay in WAL replay on a standby — the standby receives WAL in real-time but waits the specified duration before applying it, creating a time-lagged replica for disaster recovery', 'Delay before starting recovery', 'Minimum delay between checkpoints'], correctAnswer: 1, explanation: 'recovery_min_apply_delay creates a deliberate lag between receiving and applying WAL. The standby data is intentionally behind the primary by the configured time. This provides a safety net against accidental data destruction: if someone drops a table, you have a time window to rescue the data from the delayed standby.', codeSnippet: "-- On standby: postgresql.conf\nrecovery_min_apply_delay = '1 hour'\n\n-- The standby:\n-- 1. Receives WAL in real-time (no network lag)\n-- 2. Holds WAL in local pg_wal\n-- 3. Applies WAL only after 1-hour delay\n\n-- Verify delay:\nSELECT now() - pg_last_xact_replay_timestamp() AS current_delay;\n-- Should show approximately 1 hour\n\n-- Good values:\n-- 15 minutes: quick recovery window\n-- 1 hour: standard safety margin\n-- 24 hours: for protection against overnight mistakes", tags: ['admin', 'replication', 'delayed-standby', 'recovery-delay'] },
  { id: 'pg-admin-l3-062', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'WAL Archiving', question: 'What is the relationship between WAL archiving and replication slots?', options: ['They are the same feature', 'WAL archiving saves completed segments to an external location; replication slots prevent WAL segment recycling in pg_wal — they serve different purposes but both ensure WAL availability for consumers', 'Replication slots replace WAL archiving', 'WAL archiving requires replication slots'], correctAnswer: 1, explanation: 'WAL archiving copies WAL to external storage for PITR backup. Replication slots prevent pg_wal cleanup for specific consumers (standbys, logical decoders). They complement each other: slots ensure WAL is available in pg_wal for active standbys; archiving preserves WAL long-term for PITR and for standbys that need to catch up after extended downtime.', codeSnippet: "-- WAL archiving: external backup\narchive_mode = on\narchive_command = 'cp %p /archive/%f'\n-- Copies WAL to archive for PITR\n\n-- Replication slot: prevents premature recycling\nSELECT pg_create_physical_replication_slot('my_standby');\n-- Keeps WAL in pg_wal until standby confirms receipt\n\n-- Both together:\n-- Slot ensures standby doesn't miss WAL during brief disconnects\n-- Archive ensures WAL is available after long disconnects\n-- or for PITR to any historical point\n\n-- Monitor both:\nSELECT * FROM pg_stat_archiver;  -- archive status\nSELECT * FROM pg_replication_slots;  -- slot status", tags: ['admin', 'wal-archiving', 'replication-slots', 'relationship'] },
  { id: 'pg-admin-l3-063', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'How do you perform PITR using pgBackRest?', options: ['The same as manual PITR', 'pgBackRest manages the entire PITR workflow: automated base backups, continuous WAL archiving, and restore with --type=time/xid/lsn/name — it handles all the complexity of backup management, retention, and verification', 'pgBackRest does not support PITR', 'Only through the command line'], correctAnswer: 1, explanation: 'pgBackRest simplifies PITR by managing backups, WAL archiving, and restoration as integrated operations. It supports full, differential, and incremental backups, parallel backup/restore, compression, encryption, and multiple repository backends (local, S3, GCS, Azure). It is the recommended backup tool for production PostgreSQL.', codeSnippet: "# Configure pgBackRest:\n# /etc/pgbackrest/pgbackrest.conf\n# [mydb]\n# pg1-path=/var/lib/postgresql/data\n# [global]\n# repo1-path=/backup/pgbackrest\n# repo1-retention-full=2\n\n# postgresql.conf:\narchive_command = 'pgbackrest --stanza=mydb archive-push %p'\nrestore_command = 'pgbackrest --stanza=mydb archive-get %f \"%p\"'\n\n# Take backup:\npgbackrest --stanza=mydb --type=full backup\n\n# PITR restore:\npgbackrest --stanza=mydb --type=time \\\n  --target='2024-06-15 14:30:00' \\\n  --target-action=promote restore\n\n# Start PostgreSQL:\npg_ctl start -D /var/lib/postgresql/data", tags: ['admin', 'pitr', 'pgbackrest', 'backup-tool'] },
  { id: 'pg-admin-l3-064', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Connection Pooling', question: 'What is the so_reuseport option in pgBouncer?', options: ['Reuses database connections', 'Enables SO_REUSEPORT socket option allowing multiple pgBouncer processes to bind to the same port — enables zero-downtime restarts and multi-process load sharing', 'Reuses client ports', 'Allows port forwarding'], correctAnswer: 1, explanation: 'SO_REUSEPORT (pgBouncer 1.18+) allows multiple processes to listen on the same address:port. This enables: zero-downtime restarts (new process binds while old drains), multi-process pgBouncer for utilizing multiple CPU cores, and seamless configuration reload.', codeSnippet: "-- pgbouncer.ini:\nso_reuseport = 1\n\n-- Zero-downtime restart:\n# 1. Start new pgBouncer with same config:\npgbouncer /etc/pgbouncer/pgbouncer.ini\n# Both old and new accept connections\n\n# 2. Signal old pgBouncer to drain and exit:\nkill -SIGINT <old_pid>\n# Old process finishes existing queries then exits\n# New process serves all new connections\n\n-- Or use the online restart command:\npgbouncer -R /etc/pgbouncer/pgbouncer.ini", tags: ['admin', 'pgbouncer', 'so-reuseport', 'zero-downtime'] },
  { id: 'pg-admin-l3-065', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Streaming Replication', question: 'What is full_page_writes and how does it affect replication?', options: ['Writes entire pages to disk', 'When enabled (default), PostgreSQL writes the full page image to WAL on the first modification after a checkpoint — prevents partial page writes from causing corruption, but increases WAL volume and replication bandwidth', 'Enables full-text search on replicas', 'Writes all pages during vacuum'], correctAnswer: 1, explanation: 'After a checkpoint, the first modification to any page writes the entire 8KB page to WAL (FPI - Full Page Image). This protects against torn pages (partial disk writes during crash). FPIs significantly increase WAL volume (2-3x). wal_compression can compress FPIs to reduce WAL size and replication bandwidth.', codeSnippet: "-- Default: enabled (required for data safety)\nfull_page_writes = on\n\n-- Reduce FPI overhead with compression:\nwal_compression = on   -- PG 15+: or 'zstd', 'lz4', 'pglz'\n\n-- Check FPI ratio in WAL:\nSELECT wal_records, wal_fpi,\n  round(100.0 * wal_fpi / NULLIF(wal_records, 0), 1) AS fpi_pct,\n  pg_size_pretty(wal_bytes) AS total_wal\nFROM pg_stat_wal;\n\n-- High fpi_pct after checkpoint? Normal.\n-- Reduce by increasing checkpoint_timeout\n-- (fewer checkpoints = fewer FPIs)", tags: ['admin', 'replication', 'full-page-writes', 'wal-volume'] },
  { id: 'pg-admin-l3-066', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'What is the role of pg_control in recovery?', options: ['Controls PostgreSQL settings', 'The pg_control file stores critical cluster state including the last checkpoint location, timeline ID, and database system identifier — PostgreSQL reads it at startup to determine if recovery is needed and where to start', 'Controls access permissions', 'Controls WAL generation speed'], correctAnswer: 1, explanation: 'pg_control (in the data directory) is the critical control file containing: last checkpoint location, timeline ID, database state (in production/recovery/shutting down), system identifier, and WAL segment size. It is read at startup to determine recovery needs. Corruption of pg_control can require pg_resetwal (last resort).', codeSnippet: "-- View pg_control contents:\npg_controldata /var/lib/postgresql/data\n\n-- Key fields:\n-- Database cluster state: in production\n-- Latest checkpoint location: 0/1A000060\n-- Latest checkpoint's TimeLineID: 1\n-- Database system identifier: 7123456789012345\n\n-- SQL function (PG 12+):\nSELECT * FROM pg_control_checkpoint();\nSELECT * FROM pg_control_system();\nSELECT * FROM pg_control_recovery();\n\n-- Emergency tool (LAST RESORT):\n-- pg_resetwal -D /var/lib/postgresql/data\n-- WARNING: may cause data loss", tags: ['admin', 'pitr', 'pg-control', 'recovery'] },
  { id: 'pg-admin-l3-067', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Streaming Replication', question: 'How do you monitor WAL disk usage and prevent disk full?', options: ['PostgreSQL handles this automatically', 'Monitor pg_wal directory size, set max_wal_size to control checkpoint frequency, use replication slots carefully (stale slots accumulate WAL), and set max_slot_wal_keep_size (PG 13+) to limit WAL retained per slot', 'Use disk quotas', 'WAL cannot fill the disk'], correctAnswer: 1, explanation: 'WAL disk usage grows with: large transactions, many checkpoints, stale replication slots, and WAL archiving failures. max_slot_wal_keep_size (PG 13+) caps per-slot WAL retention, preventing a stale slot from filling the disk. Monitor pg_wal size and slot lag, and alert before disk fills.', codeSnippet: "-- Limit WAL retention per slot (PG 13+):\nmax_slot_wal_keep_size = 10GB\n\n-- Monitor pg_wal size:\nSELECT pg_size_pretty(sum(size))\nFROM pg_ls_waldir();\n\n-- Check slot WAL retention:\nSELECT slot_name, active,\n  pg_size_pretty(\n    pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn)\n  ) AS retained_wal\nFROM pg_replication_slots\nORDER BY pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn) DESC;\n\n-- Drop stale slots:\nSELECT pg_drop_replication_slot('stale_slot');", tags: ['admin', 'replication', 'wal-disk-usage', 'monitoring'] },
  { id: 'pg-admin-l3-068', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Connection Pooling', question: 'What is the peer_addr tracking in pgBouncer?', options: ['Tracks peer-to-peer connections', 'pgBouncer tracks original client IP addresses and can pass them to PostgreSQL — this preserves client identity for logging and pg_stat_activity even when connections are pooled', 'Monitors peer network performance', 'Authenticates peer connections'], correctAnswer: 1, explanation: 'By default, PostgreSQL sees all connections from pgBouncer as coming from the pgBouncer host. Using application_name_add_host or PROXY protocol, the original client IP can be preserved. This is important for auditing, access control, and troubleshooting.', codeSnippet: "-- pgbouncer.ini:\napplication_name_add_host = 1\n-- Appends client IP to application_name\n\n-- In pg_stat_activity:\n-- application_name: 'myapp - 192.168.1.50:43210'\n\n-- Alternative: log connections in pgBouncer\nlog_connections = 1\nlog_disconnections = 1\n\n-- pgBouncer SHOW CLIENTS shows real client IPs:\n-- SHOW CLIENTS;\n-- addr | port | local_addr | local_port | state", tags: ['admin', 'pgbouncer', 'client-tracking', 'auditing'] },
  { id: 'pg-admin-l3-069', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Streaming Replication', question: 'What is pg_auto_failover?', options: ['A pgBouncer feature', 'A PostgreSQL extension and service that implements automatic failover for streaming replication — monitors primary and standby health and promotes standby automatically when the primary fails', 'A WAL management tool', 'A backup automation tool'], correctAnswer: 1, explanation: 'pg_auto_failover is an open-source tool that provides automatic failover for PostgreSQL. It uses a monitor node that tracks health of primary and standbys. When the primary fails, it automatically promotes a standby. It handles the complexity of split-brain prevention, fencing, and state management.', codeSnippet: "# Initialize the monitor:\npg_autoctl create monitor \\\n  --pgdata=/var/lib/postgresql/monitor \\\n  --pgport=5000\n\n# Initialize primary:\npg_autoctl create postgres \\\n  --pgdata=/var/lib/postgresql/data \\\n  --pgport=5432 \\\n  --monitor='postgres://autoctl@monitor:5000/pg_auto_failover'\n\n# Initialize standby:\npg_autoctl create postgres \\\n  --pgdata=/var/lib/postgresql/data \\\n  --pgport=5432 \\\n  --monitor='postgres://autoctl@monitor:5000/pg_auto_failover'\n\n# Run the service:\npg_autoctl run", tags: ['admin', 'replication', 'auto-failover', 'high-availability'] },
  { id: 'pg-admin-l3-070', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'WAL Archiving', question: 'What is wal_compression?', options: ['Compresses the WAL directory', 'Compresses full-page images written to WAL — reduces WAL size, disk I/O, and replication bandwidth; PostgreSQL 15+ supports multiple compression methods (pglz, lz4, zstd)', 'Compresses WAL archive files', 'Compresses WAL network transfer'], correctAnswer: 1, explanation: 'wal_compression compresses full-page images (FPIs) within WAL records. Since FPIs are the bulk of WAL volume (especially after checkpoints), this can reduce WAL size by 30-60%. PG 15+ supports lz4 and zstd which are faster than the original pglz. The tradeoff is CPU usage for compression/decompression.', codeSnippet: "-- Enable WAL compression:\nwal_compression = on    -- PG 9.5+: uses pglz\nwal_compression = lz4   -- PG 15+: faster\nwal_compression = zstd  -- PG 15+: best ratio\n\n-- Monitor compression effectiveness:\nSELECT pg_size_pretty(wal_bytes) AS total_wal,\n  wal_fpi AS full_page_images\nFROM pg_stat_wal;\n\n-- Before compression: ~2GB WAL/hour\n-- After compression:  ~1GB WAL/hour (typical)\n\n-- CPU overhead is usually negligible\n-- compared to I/O savings", tags: ['admin', 'wal', 'compression', 'performance'] },
  { id: 'pg-admin-l3-071', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'What are the prerequisites for a successful PITR?', options: ['Just a pg_dump backup', 'A consistent base backup (pg_basebackup), all WAL segments from the backup start to the recovery target, and correct configuration of restore_command and recovery target parameters', 'Only the latest WAL segment', 'Just the data directory copy'], correctAnswer: 1, explanation: 'PITR requires: (1) a base backup taken with pg_basebackup or pg_backup_start/stop, (2) an unbroken chain of WAL segments from the backup start LSN to the desired recovery point, (3) correct restore_command to access archived WAL, (4) correct recovery target settings. Missing any WAL segment breaks the chain and limits recovery.', codeSnippet: "-- PITR prerequisites checklist:\n\n-- 1. Base backup (must exist):\npg_basebackup -D /backup/base -Fp -Xs -P\n\n-- 2. Continuous WAL archive (must be unbroken):\narchive_mode = on\narchive_command = 'cp %p /archive/wal/%f'\n-- Verify: ls /archive/wal/ | sort | head\n\n-- 3. Recovery configuration:\nrestore_command = 'cp /archive/wal/%f %p'\nrecovery_target_time = '2024-06-15 14:30:00'\nrecovery_target_action = 'promote'\n\n-- 4. Verify WAL chain is complete:\n-- No gaps between backup start LSN and target time\n-- Check: ls /archive/wal/ | sort\n-- Files should be sequential", tags: ['admin', 'pitr', 'prerequisites', 'checklist'] },
  { id: 'pg-admin-l3-072', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Connection Pooling', question: 'What happens to prepared transactions with pgBouncer?', options: ['They work normally', 'Prepared transactions (PREPARE TRANSACTION) are problematic with pgBouncer transaction pooling because the connection is returned to the pool after PREPARE, but the transaction lock persists on the server — avoid two-phase commit or use session mode', 'pgBouncer handles them automatically', 'They are faster with pooling'], correctAnswer: 1, explanation: 'Two-phase commit (PREPARE TRANSACTION) acquires locks that persist until COMMIT PREPARED or ROLLBACK PREPARED. In transaction mode, the connection is returned to the pool after PREPARE TRANSACTION, but another client gets the same connection with the prepared transaction still holding locks. This can cause deadlocks and resource leaks.', codeSnippet: "-- Problem: prepared transactions in transaction mode\n\n-- Client 1:\nBEGIN;\n-- ... work ...\nPREPARE TRANSACTION 'tx1';\n-- Connection returned to pool!\n\n-- Client 2 gets same connection:\nBEGIN;\nSELECT * FROM locked_table;  -- BLOCKED by tx1!\n\n-- Solution 1: Use session mode for 2PC:\npool_mode = session\n\n-- Solution 2: Avoid 2PC entirely\n-- Use single-database transactions\n\n-- Solution 3: COMMIT PREPARED in same transaction:\nBEGIN;\nCOMMIT PREPARED 'tx1';\nCOMMIT;", tags: ['admin', 'pgbouncer', 'prepared-transactions', 'two-phase-commit'] },
  { id: 'pg-admin-l3-073', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Streaming Replication', question: 'What is the primary_conninfo setting?', options: ['Primary database configuration', 'The connection string on a standby server that specifies how to connect to the primary for streaming replication — includes host, port, user, password, and optional SSL settings', 'Primary server IP address', 'Connection count on primary'], correctAnswer: 1, explanation: 'primary_conninfo is set on the standby (in postgresql.conf or postgresql.auto.conf) and contains the libpq connection string for reaching the primary server. It includes host, port, user, password (or passfile), sslmode, and application_name. pg_basebackup -R auto-configures this.', codeSnippet: "-- On standby: postgresql.conf or postgresql.auto.conf\nprimary_conninfo = 'host=primary port=5432 user=repl_user password=secret application_name=standby1'\n\n-- With SSL:\nprimary_conninfo = 'host=primary port=5432 user=repl_user sslmode=require sslcert=/path/cert sslkey=/path/key'\n\n-- With passfile (avoid password in config):\nprimary_conninfo = 'host=primary port=5432 user=repl_user passfile=/var/lib/postgresql/.pgpass'\n\n-- Using a slot:\nprimary_slot_name = 'standby1_slot'", tags: ['admin', 'replication', 'primary-conninfo', 'standby-config'] },
  { id: 'pg-admin-l3-074', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'WAL Archiving', question: 'How do you handle WAL archiving failures gracefully?', options: ['Ignore them', 'Implement monitoring on pg_stat_archiver.failed_count, use a robust archive_command with proper error handling, set up alerts for consecutive failures, and ensure the archive destination has sufficient space', 'Restart PostgreSQL', 'Disable archiving temporarily'], correctAnswer: 1, explanation: 'Archiving failures are serious: WAL accumulates, potentially filling the disk and crashing PostgreSQL. Best practices: (1) archive_command should handle transient failures (retry logic), (2) monitor failed_count, (3) alert on any failures, (4) ensure archive destination has ample space, (5) test archive_command regularly.', codeSnippet: "-- Robust archive_command with error handling:\narchive_command = 'test ! -f /archive/wal/%f && cp %p /archive/wal/%f || (logger -t pg_archive \"FAILED: %f\" && false)'\n\n-- Monitor archiving health:\nSELECT\n  CASE WHEN failed_count > 0\n    THEN 'ALERT: ' || failed_count || ' failures'\n    ELSE 'OK'\n  END AS status,\n  last_archived_wal,\n  last_archived_time,\n  last_failed_wal,\n  last_failed_time\nFROM pg_stat_archiver;\n\n-- Check WAL accumulation:\nSELECT count(*) AS pending_wal_files\nFROM pg_ls_waldir()\nWHERE modification < now() - interval '10 minutes';", tags: ['admin', 'wal-archiving', 'failure-handling', 'monitoring'] },
  { id: 'pg-admin-l3-075', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'What is pg_backup_start() and pg_backup_stop()?', options: ['Functions to start and stop the server', 'Functions that mark the beginning and end of a manual base backup — pg_backup_start() forces a checkpoint and pg_backup_stop() returns the backup label; required when taking file-system-level backups without pg_basebackup', 'Functions to start and stop replication', 'Functions to enable and disable backups'], correctAnswer: 1, explanation: 'pg_backup_start() (previously pg_start_backup()) begins a base backup session: forces a checkpoint and records the start LSN. You then copy the data directory. pg_backup_stop() (previously pg_stop_backup()) ends the session and returns the backup_label and tablespace_map content needed for recovery.', codeSnippet: "-- Manual file-system backup process:\n\n-- Step 1: Start backup\nSELECT pg_backup_start('manual_backup', fast := true);\n-- fast=true: immediate checkpoint\n\n-- Step 2: Copy data directory (while server is running)\n-- rsync, cp, ZFS snapshot, LVM snapshot, etc.\n-- rsync -a /var/lib/postgresql/data/ /backup/base/\n\n-- Step 3: Stop backup\nSELECT * FROM pg_backup_stop(wait_for_archive := true);\n-- Returns: lsn, labelfile, spcmapfile\n-- Save labelfile as backup_label in the backup\n-- Save spcmapfile as tablespace_map in the backup\n\n-- Note: pg_basebackup handles all this automatically", tags: ['admin', 'pitr', 'pg-backup-start', 'manual-backup'] },
  { id: 'pg-admin-l3-076', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Connection Pooling', question: 'How do you handle LISTEN/NOTIFY with pgBouncer?', options: ['LISTEN/NOTIFY works normally', 'LISTEN/NOTIFY requires session pooling mode because notifications are delivered to the connection that issued LISTEN — in transaction mode, the connection is returned to the pool and notifications are lost', 'Use NOTIFY only, not LISTEN', 'pgBouncer has its own notification system'], correctAnswer: 1, explanation: 'LISTEN registers interest in a notification channel on a specific connection. In transaction mode, the connection is returned to the pool after each transaction, losing the LISTEN registration. Notifications are then never delivered. Applications using LISTEN/NOTIFY must use session mode or a dedicated non-pooled connection.', codeSnippet: "-- Problem: transaction mode\nBEGIN;\nLISTEN my_channel;\nCOMMIT;\n-- Connection returned to pool! LISTEN is lost.\n\n-- Solution 1: Session mode for LISTEN connections\n[databases]\nmydb_notify = host=db1 dbname=mydb pool_mode=session\nmydb = host=db1 dbname=mydb pool_mode=transaction\n\n-- Solution 2: Direct connection for LISTEN\n-- Bypass pgBouncer for notification listener\n-- Connect directly to PostgreSQL port 5432\n\n-- Solution 3: Use polling instead of LISTEN\n-- Application periodically checks a status table", tags: ['admin', 'pgbouncer', 'listen-notify', 'session-mode'] },
  { id: 'pg-admin-l3-077', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Streaming Replication', question: 'What is data checksums and how does it relate to replication?', options: ['Checksums for data exports', 'Data checksums detect data corruption at the page level — they are computed when pages are written and verified when read; essential for detecting silent corruption that could be replicated to standbys', 'Network checksums for WAL', 'Backup verification checksums'], correctAnswer: 1, explanation: 'Data checksums (enabled with initdb --data-checksums or pg_checksums) protect against silent data corruption (bit rot, firmware bugs). Without checksums, corrupted data is silently replicated to standbys. With checksums, corruption is detected on read, triggering an error instead of returning wrong data.', codeSnippet: "-- Check if checksums are enabled:\nSHOW data_checksums;  -- on or off\n\n-- Enable on existing cluster (PG 12+):\n-- Requires downtime!\npg_checksums --enable -D /var/lib/postgresql/data\n\n-- Enable during initdb:\ninitdb --data-checksums -D /var/lib/postgresql/data\n\n-- Verify checksums:\npg_checksums --check -D /var/lib/postgresql/data\n\n-- When corruption is detected:\n-- WARNING: page verification failed, calculated checksum\n-- 12345 but expected 67890\n-- ERROR: invalid page in block 42 of relation ...", tags: ['admin', 'replication', 'data-checksums', 'corruption'] },
  { id: 'pg-admin-l3-078', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'WAL Archiving', question: 'What is the difference between WAL archiving and WAL shipping?', options: ['They are identical', 'WAL archiving copies completed segments to storage via archive_command; WAL shipping refers to transferring archived WAL segments to a standby restore_command — archiving is the push, shipping is the pull, and streaming replication superseded both', 'WAL shipping is faster', 'WAL archiving is deprecated'], correctAnswer: 1, explanation: 'WAL archiving (archive_command) copies completed 16MB WAL segments to storage. WAL shipping (log-shipping) was the original replication method: primary archives WAL, standby retrieves it via restore_command. Streaming replication (sends WAL records in real-time) largely replaced log-shipping for replication but archiving is still needed for PITR.', codeSnippet: "-- WAL Archiving (primary pushes to archive):\narchive_command = 'cp %p /shared_archive/%f'\n\n-- WAL Shipping (standby pulls from archive):\nrestore_command = 'cp /shared_archive/%f %p'\n-- Lag: up to 1 WAL segment (16MB of changes)\n\n-- Streaming Replication (real-time):\nprimary_conninfo = 'host=primary ...'\n-- Lag: typically < 1 second\n\n-- Modern setup: streaming + archiving:\n-- Streaming for low-lag replication\n-- Archiving for PITR and long-term backup", tags: ['admin', 'wal-archiving', 'wal-shipping', 'comparison'] },
  { id: 'pg-admin-l3-079', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Connection Pooling', question: 'What is the dns_max_ttl setting in pgBouncer?', options: ['Maximum DNS cache time', 'Controls how long pgBouncer caches DNS lookups for database hostnames — important for cloud environments where database IPs change during failover or scaling events', 'Maximum time to resolve DNS', 'DNS timeout for connections'], correctAnswer: 1, explanation: 'dns_max_ttl (default 15 seconds) controls DNS caching in pgBouncer. In cloud environments with DNS-based failover (RDS, Aurora), a stale DNS cache means pgBouncer connects to the old primary after failover. Lower values ensure faster failover detection. Set to 0 for no caching (higher DNS load).', codeSnippet: "-- pgbouncer.ini:\n\n-- Default (15 seconds):\ndns_max_ttl = 15\n\n-- For cloud databases with DNS failover:\ndns_max_ttl = 5  -- refresh every 5 seconds\n\n-- No caching (immediate failover detection):\ndns_max_ttl = 0\n\n-- Relevant for:\n-- AWS RDS (DNS changes during failover)\n-- Aurora (writer endpoint DNS)\n-- Google Cloud SQL\n-- Azure Database for PostgreSQL", tags: ['admin', 'pgbouncer', 'dns', 'cloud', 'failover'] },
  { id: 'pg-admin-l3-080', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Streaming Replication', question: 'What is Patroni and how does it enhance replication management?', options: ['A PostgreSQL monitoring tool', 'An open-source cluster management tool that automates PostgreSQL high availability — manages leader election, automatic failover, and replica management using a distributed consensus store (etcd, ZooKeeper, or Consul)', 'A pgBouncer alternative', 'A backup management tool'], correctAnswer: 1, explanation: 'Patroni runs on each PostgreSQL node and uses a DCS (distributed configuration store) for leader election and cluster state. It handles: initial cluster bootstrap, automatic failover, planned switchover, configuration management, and replica topology. It is the most popular HA solution for PostgreSQL.', codeSnippet: "# Patroni configuration (patroni.yml):\nscope: myapp-cluster\nname: node1\n\nrestapi:\n  listen: 0.0.0.0:8008\n\netcd:\n  hosts: etcd1:2379,etcd2:2379,etcd3:2379\n\npostgresql:\n  listen: 0.0.0.0:5432\n  data_dir: /var/lib/postgresql/data\n  authentication:\n    replication:\n      username: repl_user\n      password: secret\n\n# Start Patroni:\npatroni /etc/patroni/patroni.yml\n\n# Check cluster status:\npatronictlctl -c /etc/patroni/patroni.yml list\n# +--------+----------+-------+---------+\n# | Member | Host     | Role  | State   |\n# +--------+----------+-------+---------+\n# | node1  | 10.0.0.1 | Leader| running |\n# | node2  | 10.0.0.2 | Replica| streaming|", tags: ['admin', 'replication', 'patroni', 'high-availability'] },
  { id: 'pg-admin-l3-081', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'WAL Archiving', question: 'What is the impact of archive_command on write performance?', options: ['Significant impact on every write', 'Minimal impact — archive_command runs asynchronously after a WAL segment is complete; it does not block transaction commits unless archive_timeout forces frequent segment switches on a low-activity server', 'No impact at all', 'Only affects SELECT performance'], correctAnswer: 1, explanation: 'archive_command is called asynchronously when a 16MB WAL segment is complete. It does not block individual commits. However, if the archive_command is slow and segments accumulate, the pg_wal directory can fill up, eventually blocking writes. A fast archive_command (local copy or efficient remote transfer) minimizes any impact.', codeSnippet: "-- archive_command runs after segment completion\n-- Does NOT block individual commits\n\n-- Potential issues:\n-- 1. Slow archive_command -> WAL accumulation\n-- 2. Failed archive_command -> WAL never recycled\n-- 3. archive_timeout + slow command -> more overhead\n\n-- Best practices for minimal impact:\n-- Use fast local copy first, then async transfer:\narchive_command = 'cp %p /fast_local_archive/%f'\n-- Then rsync /fast_local_archive/ to remote\n\n-- Or use pgBackRest (async by design):\narchive_command = 'pgbackrest --stanza=mydb archive-push %p'", tags: ['admin', 'wal-archiving', 'performance', 'write-impact'] },
  { id: 'pg-admin-l3-082', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'How do you handle a failed PITR attempt?', options: ['The data is lost', 'The base backup is still intact — you can reconfigure the recovery target and try again; if using recovery_target_action=shutdown, the server stops at the target for inspection before committing', 'Restore from pg_dump', 'Contact PostgreSQL support'], correctAnswer: 1, explanation: 'A PITR failure does not destroy the base backup. Common issues: wrong recovery target (adjusted in config), missing WAL segments (check archive), permission errors. Use recovery_target_action=pause to inspect the state before committing. If the recovery went too far, restart from the base backup with a different target.', codeSnippet: "-- Safe PITR workflow:\n\n-- 1. Always keep the original base backup!\ncp -a /backup/base /backup/base_original\n\n-- 2. Use 'pause' to inspect before committing:\nrecovery_target_time = '2024-06-15 14:30:00'\nrecovery_target_action = 'pause'\n\n-- 3. Start recovery:\npg_ctl start -D /recovery/data\n\n-- 4. Inspect (read-only queries work):\nSELECT * FROM important_table;\n\n-- 5a. If correct: promote\nSELECT pg_promote();\n\n-- 5b. If wrong: stop and retry\npg_ctl stop -D /recovery/data\n-- Restore base backup again, adjust target\ncp -a /backup/base_original /recovery/data\n-- Edit recovery settings, try again", tags: ['admin', 'pitr', 'failure-recovery', 'troubleshooting'] },
  { id: 'pg-admin-l3-083', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Streaming Replication', question: 'What is the role of wal_log_hints in replication?', options: ['Adds hint messages to WAL', 'Enables WAL logging of hint bit changes — required for pg_rewind to work correctly because it needs to track all page modifications including hint bits', 'Logs replication hints', 'Enables query hints in WAL'], correctAnswer: 1, explanation: 'Hint bits are lightweight flags on tuples (e.g., marking a tuple as committed). Without wal_log_hints, these changes are not logged in WAL. pg_rewind needs complete WAL logging of all page modifications to safely rewind a server. Either enable wal_log_hints or use data checksums (which implicitly enable it).', codeSnippet: "-- Enable WAL logging of hint bits:\nwal_log_hints = on\n\n-- Required for:\n-- 1. pg_rewind (make old primary into standby)\n-- 2. pg_checksums (detect corruption)\n\n-- Alternative: data checksums (also enables hint logging)\ninitdb --data-checksums\n\n-- Check current setting:\nSHOW wal_log_hints;\n\n-- Note: increases WAL volume slightly\n-- Trade-off is worth it for pg_rewind capability", tags: ['admin', 'replication', 'wal-log-hints', 'pg-rewind'] },
  { id: 'pg-admin-l3-084', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Connection Pooling', question: 'What is the server_lifetime setting in pgBouncer?', options: ['Maximum server uptime', 'Maximum age of a server connection before it is closed and replaced — prevents issues from long-lived connections accumulating memory or holding stale state', 'Server certificate validity period', 'Maximum server pool size'], correctAnswer: 1, explanation: 'server_lifetime (default 3600 seconds) closes server connections that have been open longer than the specified time. This prevents issues from: memory leaks in PostgreSQL backends, stale connection state, DNS changes (failover), and ensures connections rotate. Connections are closed gracefully when returned to the pool.', codeSnippet: "-- pgbouncer.ini:\nserver_lifetime = 3600    -- 1 hour (default)\nserver_idle_timeout = 600  -- close idle connections after 10 min\n\n-- For environments with frequent failover:\nserver_lifetime = 300     -- 5 minutes\n\n-- Disable (connections live forever):\nserver_lifetime = 0\n\n-- Related settings:\nserver_connect_timeout = 15  -- timeout for new connections\nserver_login_retry = 15      -- retry delay after failure", tags: ['admin', 'pgbouncer', 'server-lifetime', 'connection-management'] },
  { id: 'pg-admin-l3-085', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Streaming Replication', question: 'How do you perform a planned switchover (role swap)?', options: ['Promote the standby and hope for the best', 'Stop writes on the primary, ensure standby is caught up (zero lag), promote the standby, then reconfigure the old primary as a standby — or use pg_rewind for faster reconfiguration', 'Restart both servers', 'Use ALTER SYSTEM SWITCHOVER'], correctAnswer: 1, explanation: 'A planned switchover safely swaps primary and standby roles. Steps: (1) stop application writes, (2) wait for replication lag to reach zero, (3) shut down old primary, (4) promote standby, (5) reconfigure old primary as standby (pg_rewind or pg_basebackup), (6) start old primary as standby, (7) resume application writes to new primary.', codeSnippet: "-- Step 1: Verify standby is caught up\nSELECT client_addr,\n  pg_wal_lsn_diff(sent_lsn, replay_lsn) AS lag\nFROM pg_stat_replication;\n-- lag should be 0\n\n-- Step 2: Stop old primary\npg_ctl stop -D /primary/data -m fast\n\n-- Step 3: Promote standby\nSELECT pg_promote();\n-- Or: pg_ctl promote -D /standby/data\n\n-- Step 4: Reconfigure old primary as standby\npg_rewind --target-pgdata=/primary/data \\\n  --source-server='host=new_primary user=repl_user'\ntouch /primary/data/standby.signal\n\n-- Step 5: Start old primary as standby\npg_ctl start -D /primary/data", tags: ['admin', 'replication', 'switchover', 'role-swap'] },
  { id: 'pg-admin-l3-086', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Point-in-Time Recovery', question: 'What is incremental backup in PostgreSQL 17+?', options: ['Only backs up changed files', 'PostgreSQL 17 introduced pg_basebackup --incremental which only backs up pages modified since the last backup — reduces backup size and duration while maintaining PITR capability', 'Incremental ANALYZE', 'Incremental VACUUM'], correctAnswer: 1, explanation: 'PostgreSQL 17 added native incremental backup support to pg_basebackup. It tracks which pages changed since a prior backup using WAL summarization (pg_walsummary). Only modified pages are included in the incremental backup. Combined with pg_combinebackup for restore, this dramatically reduces backup storage and time.', codeSnippet: "-- Enable WAL summarization (PG 17+):\nsummarize_wal = on\n\n-- Take full backup:\npg_basebackup -D /backup/full --checkpoint=fast -Fp\n\n-- Take incremental backup:\npg_basebackup -D /backup/incr1 \\\n  --incremental=/backup/full/backup_manifest\n\n-- Combine for restore:\npg_combinebackup /backup/full /backup/incr1 -o /recovery/data\n\n-- Start recovery:\npg_ctl start -D /recovery/data", tags: ['admin', 'pitr', 'incremental-backup', 'pg17'] },
  { id: 'pg-admin-l3-087', language: 'postgresql', level: 'level3', category: 'Administration', subcategory: 'Connection Pooling', question: 'How do you handle SSL/TLS with pgBouncer?', options: ['SSL is not supported', 'pgBouncer supports SSL on both client-facing and server-facing connections independently — configure client_tls_* for client connections and server_tls_* for database connections', 'SSL is automatic', 'Only server-side SSL works'], correctAnswer: 1, explanation: 'pgBouncer can terminate SSL from clients (client_tls_*) and establish SSL to PostgreSQL (server_tls_*). This allows: SSL everywhere, SSL only on the client side (if pgBouncer is co-located with PostgreSQL), or SSL only on the server side. Certificate authentication is also supported.', codeSnippet: "-- pgbouncer.ini:\n\n-- Client-facing SSL:\nclient_tls_sslmode = require\nclient_tls_key_file = /etc/pgbouncer/server.key\nclient_tls_cert_file = /etc/pgbouncer/server.crt\nclient_tls_ca_file = /etc/pgbouncer/ca.crt\n\n-- Server-facing SSL (to PostgreSQL):\nserver_tls_sslmode = verify-full\nserver_tls_ca_file = /etc/pgbouncer/pg-ca.crt\n\n-- TLS protocol versions:\nclient_tls_protocols = tlsv1.2,tlsv1.3\nclient_tls_ciphers = HIGH:!aNULL:!MD5", tags: ['admin', 'pgbouncer', 'ssl', 'tls', 'security'] },
];

export default questions;
